export enum BatteryChemistry {
  LI_ION = 'Li-ion (NMC/NCA)',
  LIFEPO4 = 'LiFePO4 (LFP)',
  LIPO = 'Li-Polymer'
}

export interface BatteryConfig {
  chemistry: BatteryChemistry;
  seriesCount: number;
  totalCapacityAh: number;
  nominalCellVoltage: number;
  maxCellVoltage: number;
  minCellVoltage: number;
}

export interface BatteryState {
  measuredVoltage: number;
  bmsVoltage: number;
  remainingCapacityAh: number;
  socPercentage: number;
}

export interface CalculationResult {
  estimatedSOC: number;
  totalEnergyWh: number;
  remainingEnergyWh: number;
  voltagePerCell: number;
  estimatedRemainingAh: number;
}

import { SOC_MAPS } from './constants';
import { BatteryChemistry } from './types';

/**
 * Linearly interpolates SOC based on voltage.
 */
export const getSOCFromVoltage = (cellVoltage: number, chemistry: BatteryChemistry): number => {
  const map = SOC_MAPS[chemistry];

  if (cellVoltage >= map[0].v) return 100;
  if (cellVoltage <= map[map.length - 1].v) return 0;

  for (let i = 0; i < map.length - 1; i++) {
    const high = map[i];
    const low = map[i + 1];

    if (cellVoltage <= high.v && cellVoltage >= low.v) {
      const range = high.v - low.v;
      const progress = cellVoltage - low.v;
      const ratio = progress / range;
      return low.soc + ratio * (high.soc - low.soc);
    }
  }
  return 0;
};

/**
 * Estimates voltage from SOC percentage.
 */
export const getVoltageFromSOC = (soc: number, chemistry: BatteryChemistry): number => {
  const map = SOC_MAPS[chemistry];
  const sortedBySoc = [...map].sort((a, b) => a.soc - b.soc);

  if (soc >= 100) return map[0].v;
  if (soc <= 0) return map[map.length - 1].v;

  for (let i = 0; i < sortedBySoc.length - 1; i++) {
    const low = sortedBySoc[i];
    const high = sortedBySoc[i + 1];

    if (soc >= low.soc && soc <= high.soc) {
      const range = high.soc - low.soc;
      const progress = soc - low.soc;
      const ratio = progress / range;
      return low.v + ratio * (high.v - low.v);
    }
  }
  return sortedBySoc[0].v;
};

import { GoogleGenAI } from "@google/genai";

export const getBatteryInsights = async (
  chemistry: string,
  voltage: number,
  soc: number,
  cellCount: number,
  bmsVoltage: number,
  capacityAh: number
) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = 'gemini-3-flash-preview';

  const prompt = `
    Act as a professional battery systems engineer. 
    Analyze the following battery state:
    - Chemistry: ${chemistry}
    - Configuration: ${cellCount}S
    - Total Pack Voltage: ${voltage}V
    - BMS Reported Voltage: ${bmsVoltage}V
    - State of Charge (SOC): ${soc.toFixed(1)}%
    - Total Capacity: ${capacityAh}Ah

    Provide:
    1. A brief assessment of the battery health/state based on these parameters.
    2. Check for discrepancies between pack voltage and BMS voltage.
    3. Advice on storage or charging at this level.
    4. Estimated time to full charge if charging at a standard 0.5C rate from this point.

    Keep the tone professional and concise. Format with bullet points.
  `;

  try {
    const result = await ai.models.generateContent({
      model,
      contents: prompt,
    });
    return result.text;
  } catch (error) {
    console.error("Gemini Insight Error:", error);
    return "Unable to generate AI insights at this time.";
  }
};

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { 
  Zap, 
  Battery, 
  Activity, 
  Settings, 
  Info, 
  RefreshCw,
  TrendingDown,
  AlertTriangle
} from 'lucide-react';
import { 
  LineChart, 
  Line, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  AreaChart,
  Area,
  ReferenceLine
} from 'recharts';
import { BatteryChemistry, BatteryConfig, BatteryState } from './types';
import { CHEMISTRY_DEFAULTS, SOC_MAPS } from './constants';
import { getSOCFromVoltage, getVoltageFromSOC } from './utils';
import { getBatteryInsights } from './geminiService';

const App: React.FC = () => {
  // Configuration State
  const [config, setConfig] = useState<BatteryConfig>({
    chemistry: BatteryChemistry.LI_ION,
    seriesCount: 13, // 48V nominal
    totalCapacityAh: 20,
    nominalCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LI_ION].nominal,
    maxCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LI_ION].max,
    minCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LI_ION].min
  });

  // Dynamic Battery State
  const [state, setState] = useState<BatteryState>({
    measuredVoltage: 48.1,
    bmsVoltage: 48.0,
    remainingCapacityAh: 10,
    socPercentage: 50
  });

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState<boolean>(false);

  // Synchronize derived values
  const totalEnergyWh = config.totalCapacityAh * config.nominalCellVoltage * config.seriesCount;
  const currentCellVoltage = state.measuredVoltage / config.seriesCount;

  // Handle Input Changes
  const updateMeasuredVoltage = (val: number) => {
    const soc = getSOCFromVoltage(val / config.seriesCount, config.chemistry);
    const remAh = (soc / 100) * config.totalCapacityAh;
    setState(prev => ({ 
      ...prev, 
      measuredVoltage: val, 
      socPercentage: soc,
      remainingCapacityAh: remAh
    }));
  };

  const updateSOC = (val: number) => {
    const cellV = getVoltageFromSOC(val, config.chemistry);
    const totalV = cellV * config.seriesCount;
    const remAh = (val / 100) * config.totalCapacityAh;
    setState(prev => ({ 
      ...prev, 
      socPercentage: val, 
      measuredVoltage: totalV,
      remainingCapacityAh: remAh
    }));
  };

  const updateRemainingAh = (val: number) => {
    const soc = (val / config.totalCapacityAh) * 100;
    const cellV = getVoltageFromSOC(soc, config.chemistry);
    setState(prev => ({ 
      ...prev, 
      remainingCapacityAh: val, 
      socPercentage: soc,
      measuredVoltage: cellV * config.seriesCount
    }));
  };

  const handleChemistryChange = (chem: BatteryChemistry) => {
    const defaults = CHEMISTRY_DEFAULTS[chem];
    setConfig(prev => ({
      ...prev,
      chemistry: chem,
      nominalCellVoltage: defaults.nominal,
      maxCellVoltage: defaults.max,
      minCellVoltage: defaults.min
    }));
    // Recalculate everything with new chemistry defaults
    const newCellV = getVoltageFromSOC(state.socPercentage, chem);
    setState(prev => ({
      ...prev,
      measuredVoltage: newCellV * config.seriesCount
    }));
  };

  const fetchInsights = useCallback(async () => {
    setIsAiLoading(true);
    const insights = await getBatteryInsights(
      config.chemistry,
      state.measuredVoltage,
      state.socPercentage,
      config.seriesCount,
      state.bmsVoltage,
      config.totalCapacityAh
    );
    setAiInsights(insights || 'No insights available.');
    setIsAiLoading(false);
  }, [config, state]);

  // Chart Data Preparation
  const chartData = useMemo(() => {
    return SOC_MAPS[config.chemistry].map(point => ({
      soc: point.soc,
      voltage: (point.v * config.seriesCount).toFixed(2),
      cellVoltage: point.v.toFixed(3)
    })).sort((a, b) => a.soc - b.soc);
  }, [config.chemistry, config.seriesCount]);

  return (
    <div className="min-h-screen p-4 md:p-8 max-w-7xl mx-auto space-y-6">
      {/* Header */}
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-slate-700 pb-6">
        <div>
          <h1 className="text-3xl font-bold flex items-center gap-2 text-blue-400">
            <Zap className="fill-blue-400" /> VoltSage
          </h1>
          <p className="text-slate-400 mt-1">Intelligent Battery Analysis & SOC Estimation</p>
        </div>
        <div className="flex items-center gap-3">
          <button 
            onClick={fetchInsights}
            disabled={isAiLoading}
            className="flex items-center gap-2 bg-blue-600 hover:bg-blue-500 transition-colors px-4 py-2 rounded-lg font-medium text-sm disabled:opacity-50"
          >
            {isAiLoading ? <RefreshCw className="animate-spin w-4 h-4" /> : <Activity className="w-4 h-4" />}
            Get AI Insights
          </button>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* Input Controls */}
        <div className="lg:col-span-4 space-y-6">
          <section className="bg-slate-800 rounded-2xl p-6 border border-slate-700 shadow-xl">
            <div className="flex items-center gap-2 mb-4 text-blue-400 font-semibold border-b border-slate-700 pb-2">
              <Settings size={18} /> System Configuration
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-xs uppercase tracking-wider text-slate-500 font-bold mb-1">Chemistry</label>
                <select 
                  className="w-full bg-slate-900 border border-slate-600 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
                  value={config.chemistry}
                  onChange={(e) => handleChemistryChange(e.target.value as BatteryChemistry)}
                >
                  {Object.values(BatteryChemistry).map(c => (
                    <option key={c} value={c}>{c}</option>
                  ))}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs uppercase tracking-wider text-slate-500 font-bold mb-1">Series (S)</label>
                  <input 
                    type="number" 
                    className="w-full bg-slate-900 border border-slate-600 rounded-lg px-3 py-2 outline-none"
                    value={config.seriesCount}
                    onChange={(e) => setConfig(prev => ({ ...prev, seriesCount: Math.max(1, parseInt(e.target.value) || 1) }))}
                  />
                </div>
                <div>
                  <label className="block text-xs uppercase tracking-wider text-slate-500 font-bold mb-1">Nominal V (Cell)</label>
                  <input 
                    type="number" step="0.01"
                    className="w-full bg-slate-900 border border-slate-600 rounded-lg px-3 py-2 outline-none"
                    value={config.nominalCellVoltage}
                    onChange={(e) => setConfig(prev => ({ ...prev, nominalCellVoltage: parseFloat(e.target.value) || 0 }))}
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs uppercase tracking-wider text-slate-500 font-bold mb-1">Total Capacity (Ah)</label>
                <div className="relative">
                  <input 
                    type="number" step="0.1"
                    className="w-full bg-slate-900 border border-slate-600 rounded-lg px-3 py-2 outline-none"
                    value={config.totalCapacityAh}
                    onChange={(e) => setConfig(prev => ({ ...prev, totalCapacityAh: parseFloat(e.target.value) || 0 }))}
                  />
                  <span className="absolute right-3 top-2 text-slate-500">Ah</span>
                </div>
              </div>

              <div className="p-3 bg-slate-900/50 rounded-lg border border-slate-700/50">
                <div className="text-xs text-slate-500 uppercase font-bold mb-1">Nominal Energy</div>
                <div className="text-xl font-mono text-blue-300">{totalEnergyWh.toFixed(1)} <span className="text-sm">Wh</span></div>
              </div>
            </div>
          </section>

          <section className="bg-slate-800 rounded-2xl p-6 border border-slate-700 shadow-xl">
            <div className="flex items-center gap-2 mb-4 text-emerald-400 font-semibold border-b border-slate-700 pb-2">
              <Battery size={18} /> Live Measurements
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-xs uppercase tracking-wider text-slate-500 font-bold mb-1">Pack Measured Voltage</label>
                <div className="relative">
                  <input 
                    type="number" step="0.1"
                    className="w-full bg-slate-900 border border-slate-600 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-emerald-500 text-lg font-mono"
                    value={state.measuredVoltage}
                    onChange={(e) => updateMeasuredVoltage(parseFloat(e.target.value) || 0)}
                  />
                  <span className="absolute right-3 top-2 text-slate-500">V</span>
                </div>
              </div>

              <div>
                <label className="block text-xs uppercase tracking-wider text-slate-500 font-bold mb-1">BMS Reported Voltage</label>
                <div className="relative">
                  <input 
                    type="number" step="0.1"
                    className="w-full bg-slate-900 border border-slate-600 rounded-lg px-3 py-2 outline-none"
                    value={state.bmsVoltage}
                    onChange={(e) => setState(prev => ({ ...prev, bmsVoltage: parseFloat(e.target.value) || 0 }))}
                  />
                  <span className="absolute right-3 top-2 text-slate-500">V</span>
                </div>
                {Math.abs(state.measuredVoltage - state.bmsVoltage) > 0.5 && (
                  <div className="mt-2 text-amber-400 text-xs flex items-center gap-1">
                    <AlertTriangle size={12} /> High deviation between BMS and Pack V
                  </div>
                )}
              </div>

              <div className="pt-4 border-t border-slate-700">
                <label className="block text-xs uppercase tracking-wider text-slate-500 font-bold mb-1">State of Charge (%)</label>
                <input 
                  type="range" min="0" max="100" step="1"
                  className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-emerald-500"
                  value={state.socPercentage}
                  onChange={(e) => updateSOC(parseInt(e.target.value))}
                />
                <div className="flex justify-between mt-1 text-xs text-slate-500 font-mono">
                  <span>0%</span>
                  <span className="text-emerald-400 font-bold">{state.socPercentage.toFixed(1)}%</span>
                  <span>100%</span>
                </div>
              </div>

              <div>
                <label className="block text-xs uppercase tracking-wider text-slate-500 font-bold mb-1">Remaining Capacity</label>
                <div className="relative">
                  <input 
                    type="number" step="0.1"
                    className="w-full bg-slate-900 border border-slate-600 rounded-lg px-3 py-2 outline-none"
                    value={state.remainingCapacityAh.toFixed(2)}
                    onChange={(e) => updateRemainingAh(parseFloat(e.target.value) || 0)}
                  />
                  <span className="absolute right-3 top-2 text-slate-500">Ah</span>
                </div>
              </div>
            </div>
          </section>
        </div>

        {/* Dash/Visuals */}
        <div className="lg:col-span-8 space-y-6">
          {/* Top Cards */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-slate-800 rounded-2xl p-6 border border-slate-700 shadow-xl flex flex-col justify-center">
              <div className="text-slate-500 text-xs uppercase font-bold mb-1">Cell Voltage</div>
              <div className="text-3xl font-mono font-bold text-emerald-400">{currentCellVoltage.toFixed(3)} <span className="text-sm font-normal text-slate-400">V</span></div>
              <div className="mt-2 flex items-center gap-1 text-xs text-slate-400">
                <Info size={12} /> Target: {config.nominalCellVoltage}V Nom.
              </div>
            </div>

            <div className="bg-slate-800 rounded-2xl p-6 border border-slate-700 shadow-xl flex flex-col justify-center">
              <div className="text-slate-500 text-xs uppercase font-bold mb-1">Remaining Energy</div>
              <div className="text-3xl font-mono font-bold text-blue-400">
                {((state.socPercentage / 100) * totalEnergyWh).toFixed(1)} <span className="text-sm font-normal text-slate-400">Wh</span>
              </div>
              <div className="mt-2 flex items-center gap-1 text-xs text-slate-400">
                <TrendingDown size={12} /> {((state.socPercentage / 100) * 100).toFixed(0)}% available
              </div>
            </div>

            <div className="bg-slate-800 rounded-2xl p-6 border border-slate-700 shadow-xl overflow-hidden relative">
              <div className="relative z-10">
                <div className="text-slate-500 text-xs uppercase font-bold mb-1">Charge Status</div>
                <div className="text-3xl font-mono font-bold text-emerald-400">{state.socPercentage.toFixed(1)}%</div>
                <div className="w-full bg-slate-900 h-2 rounded-full mt-4 border border-slate-700 overflow-hidden">
                  <div 
                    className={`h-full transition-all duration-500 ${state.socPercentage > 20 ? 'bg-emerald-500' : 'bg-red-500'}`}
                    style={{ width: `${state.socPercentage}%` }}
                  />
                </div>
              </div>
              <div className="absolute right-[-10px] bottom-[-10px] opacity-10">
                <Zap size={120} className="text-emerald-500" />
              </div>
            </div>
          </div>

          {/* Chart Section */}
          <section className="bg-slate-800 rounded-2xl p-6 border border-slate-700 shadow-xl">
            <h2 className="text-lg font-semibold mb-6 flex items-center gap-2">
              <Activity className="text-blue-400" size={20} /> Discharge Curve Analysis
            </h2>
            <div className="h-[300px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={chartData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                  <defs>
                    <linearGradient id="colorVoltage" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/>
                      <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
                  <XAxis 
                    dataKey="soc" 
                    stroke="#94a3b8" 
                    tick={{ fontSize: 12 }} 
                    label={{ value: 'State of Charge (%)', position: 'insideBottom', offset: -5, fill: '#64748b' }}
                  />
                  <YAxis 
                    stroke="#94a3b8" 
                    tick={{ fontSize: 12 }} 
                    domain={['auto', 'auto']}
                    label={{ value: 'Pack Voltage (V)', angle: -90, position: 'insideLeft', fill: '#64748b' }}
                  />
                  <Tooltip 
                    contentStyle={{ backgroundColor: '#1e293b', border: '1px solid #475569', borderRadius: '8px' }}
                    itemStyle={{ color: '#60a5fa' }}
                    labelStyle={{ color: '#94a3b8', marginBottom: '4px' }}
                  />
                  <Area 
                    type="monotone" 
                    dataKey="voltage" 
                    stroke="#3b82f6" 
                    strokeWidth={3}
                    fillOpacity={1} 
                    fill="url(#colorVoltage)" 
                    animationDuration={1500}
                  />
                  <ReferenceLine x={state.socPercentage} stroke="#10b981" strokeDasharray="3 3" label={{ position: 'top', value: 'CURRENT', fill: '#10b981', fontSize: 10 }} />
                </AreaChart>
              </ResponsiveContainer>
            </div>
            <p className="text-xs text-slate-500 mt-4 italic">
              * Curve represents standard discharge profile for {config.chemistry} chemistry at nominal loads.
            </p>
          </section>

          {/* AI Insights Panel */}
          <section className={`bg-slate-800 rounded-2xl p-6 border border-slate-700 shadow-xl transition-all duration-300 ${aiInsights ? 'opacity-100' : 'opacity-0 h-0 p-0 pointer-events-none overflow-hidden'}`}>
            <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
              <Zap className="text-amber-400" size={20} /> Gemini AI Analysis
            </h2>
            <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-700 text-slate-300 whitespace-pre-line leading-relaxed">
              {aiInsights}
            </div>
          </section>
        </div>
      </div>

      <footer className="text-center text-slate-600 text-xs pt-12 pb-8">
        VoltSage v1.2 &bull; Professional Battery Calculator &bull; {new Date().getFullYear()}
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useCallback } from 'react';
import { 
  Zap, 
  Battery, 
  Activity, 
  Settings, 
  Info, 
  RefreshCw,
  TrendingDown,
  AlertTriangle,
  ArrowRightLeft,
  ChevronRight
} from 'lucide-react';
import { 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  AreaChart,
  Area,
  ReferenceLine
} from 'recharts';
import { BatteryChemistry, BatteryConfig, BatteryState } from './types';
import { CHEMISTRY_DEFAULTS, SOC_MAPS } from './constants';
import { getSOCFromVoltage, getVoltageFromSOC } from './utils';
import { getBatteryInsights } from './geminiService';

const App: React.FC = () => {
  // Configuration State
  const [config, setConfig] = useState<BatteryConfig>({
    chemistry: BatteryChemistry.LI_ION,
    seriesCount: 13, 
    totalCapacityAh: 20,
    nominalCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LI_ION].nominal,
    maxCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LI_ION].max,
    minCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LI_ION].min
  });

  // Dynamic Battery State
  const [state, setState] = useState<BatteryState>({
    measuredVoltage: 48.1,
    bmsVoltage: 48.0,
    remainingCapacityAh: 10,
    socPercentage: 50
  });

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState<boolean>(false);

  // Derived Values
  const totalEnergyWh = useMemo(() => 
    config.totalCapacityAh * config.nominalCellVoltage * config.seriesCount, 
  [config.totalCapacityAh, config.nominalCellVoltage, config.seriesCount]);

  const currentCellVoltage = state.measuredVoltage / config.seriesCount;

  // Logic Handlers
  const calculateSOCFromVoltage = useCallback(() => {
    const soc = getSOCFromVoltage(state.measuredVoltage / config.seriesCount, config.chemistry);
    const remAh = (soc / 100) * config.totalCapacityAh;
    setState(prev => ({ 
      ...prev, 
      socPercentage: soc,
      remainingCapacityAh: remAh
    }));
  }, [state.measuredVoltage, config]);

  const calculateVoltageFromSOC = useCallback(() => {
    const cellV = getVoltageFromSOC(state.socPercentage, config.chemistry);
    setState(prev => ({ 
      ...prev, 
      measuredVoltage: cellV * config.seriesCount,
      remainingCapacityAh: (state.socPercentage / 100) * config.totalCapacityAh
    }));
  }, [state.socPercentage, config]);

  const updateEnergyWh = (wh: number) => {
    const ah = wh / (config.nominalCellVoltage * config.seriesCount);
    setConfig(prev => ({ ...prev, totalCapacityAh: ah }));
  };

  const handleChemistryChange = (chem: BatteryChemistry) => {
    const defaults = CHEMISTRY_DEFAULTS[chem];
    setConfig(prev => ({
      ...prev,
      chemistry: chem,
      nominalCellVoltage: defaults.nominal,
      maxCellVoltage: defaults.max,
      minCellVoltage: defaults.min
    }));
  };

  const fetchInsights = useCallback(async () => {
    setIsAiLoading(true);
    const insights = await getBatteryInsights(
      config.chemistry,
      state.measuredVoltage,
      state.socPercentage,
      config.seriesCount,
      state.bmsVoltage,
      config.totalCapacityAh
    );
    setAiInsights(insights || 'No insights available.');
    setIsAiLoading(false);
  }, [config, state]);

  const chartData = useMemo(() => {
    return SOC_MAPS[config.chemistry].map(point => ({
      soc: point.soc,
