  ocvVoltage: number; // Estimated Open Circuit Voltage
}

import { SOC_MAPS } from './constants';
import { BatteryChemistry, KalmanState } from './types';

/**
 * Linearly interpolates SOC based on voltage.
 */
export const getSOCFromVoltage = (cellVoltage: number, chemistry: BatteryChemistry): number => {
  const map = SOC_MAPS[chemistry];

  if (cellVoltage >= map[0].v) return 100;
  if (cellVoltage <= map[map.length - 1].v) return 0;

  for (let i = 0; i < map.length - 1; i++) {
    const high = map[i];
    const low = map[i + 1];

    if (cellVoltage <= high.v && cellVoltage >= low.v) {
      const range = high.v - low.v;
      const progress = cellVoltage - low.v;
      const ratio = progress / range;
      return low.soc + ratio * (high.soc - low.soc);
    }
  }
  return 0;
};

/**
 * Estimates voltage from SOC percentage.
 */
export const getVoltageFromSOC = (soc: number, chemistry: BatteryChemistry): number => {
  const map = SOC_MAPS[chemistry];
  const sortedBySoc = [...map].sort((a, b) => a.soc - b.soc);

  if (soc >= 100) return map[map.length - 1].v; // Fixed: was returning index 0 which is 100%
  if (soc <= 0) return map[map.length - 1].v;

  for (let i = 0; i < sortedBySoc.length - 1; i++) {
    const low = sortedBySoc[i];
    const high = sortedBySoc[i + 1];

    if (soc >= low.soc && soc <= high.soc) {
      const range = high.soc - low.soc;
      const progress = soc - low.soc;
      const ratio = progress / range;
      return low.v + ratio * (high.v - low.v);
    }
  }
  return sortedBySoc[0].v;
};

/**
 * Simple 1D Kalman Filter implementation for SOC smoothing.
 */
export class KalmanFilter {
  private q: number; // Process noise covariance
  private r: number; // Measurement noise covariance
  private x: number; // Value estimate
  private p: number; // Error covariance estimate
  private k: number; // Kalman gain

  constructor(processNoise = 0.01, measurementNoise = 2.0, initialState = 50) {
    this.q = processNoise;
    this.r = measurementNoise;
    this.p = 1.0;
    this.x = initialState;
    this.k = 0;
  }

  update(measurement: number): number {
    // Prediction Update
    this.p = this.p + this.q;

    // Measurement Update
    this.k = this.p / (this.p + this.r);
    this.x = this.x + this.k * (measurement - this.x);
    this.p = (1 - this.k) * this.p;

    return this.x;
  }

  getState(): KalmanState {
    return { estimate: this.x, errorCovariance: this.p };
  }

  setState(value: number) {
    this.x = value;
  }
}

/**
 * Calculates Open Circuit Voltage (OCV) by compensating for voltage droop.
 * V_ocv = V_measured + (I * R_total)
 * Where I is discharge current (positive) and R is internal resistance.
 */
export const estimateOCV = (
  measuredVoltage: number, 
  currentAmps: number, 
  seriesCount: number, 
  resistancePerCellMohm: number
): number => {
  const totalResistanceOhm = (resistancePerCellMohm / 1000) * seriesCount;
  // If current > 0 (discharging), measured voltage is LOWER than OCV. So add drop.
  // If current < 0 (charging), measured voltage is HIGHER than OCV. So subtract drop.
  return measuredVoltage + (currentAmps * totalResistanceOhm);
};

