  [state.measuredVoltage, state.currentAmps, config.seriesCount, config.internalResistanceMohm]);

  const currentCellVoltage = state.measuredVoltage / config.seriesCount;
  const ocvCellVoltage = ocvVoltage / config.seriesCount;

  // Run Kalman filter loop
  useEffect(() => {
    const calculatedRawSOC = getSOCFromVoltage(ocvCellVoltage, config.chemistry);
    setRawSOC(calculatedRawSOC);

    const timer = setInterval(() => {
      setFilteredSOC(prev => {
        const next = kFilter.current.update(calculatedRawSOC);
        // Sync remaining capacity with filtered SOC
        setState(s => ({ ...s, socPercentage: next, remainingCapacityAh: (next / 100) * config.totalCapacityAh }));
        return next;
      });
    }, 100);

    return () => clearInterval(timer);
  }, [ocvCellVoltage, config.chemistry, config.totalCapacityAh]);

  // Logic Handlers
  const calculateSOCFromVoltage = useCallback(() => {
    const soc = getSOCFromVoltage(ocvCellVoltage, config.chemistry);
