import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { 
  Zap, 
  Battery, 
  Activity, 
  Settings, 
  Info, 
  RefreshCw,
  TrendingDown,
  AlertTriangle,
  ArrowRightLeft,
  ChevronRight,
  ShieldCheck,
  Waves,
  LineChart as LucideLineChart
} from 'lucide-react';
import { 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  AreaChart,
  Area,
  ReferenceLine
} from 'recharts';
import { BatteryChemistry, BatteryConfig, BatteryState } from './types';
import { CHEMISTRY_DEFAULTS, SOC_MAPS } from './constants';
import { getSOCFromVoltage, getVoltageFromSOC, KalmanFilter, estimateOCV } from './utils';
import { getBatteryInsights } from './geminiService';

const App: React.FC = () => {
  // Configuration State
  const [config, setConfig] = useState<BatteryConfig>({
    chemistry: BatteryChemistry.LI_ION,
    seriesCount: 13, 
    totalCapacityAh: 20,
    nominalCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LI_ION].nominal,
    maxCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LI_ION].max,
    minCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LI_ION].min,
    internalResistanceMohm: 15, // Default 15mOhm per cell
    chargeRateC: 0.5 // Default 0.5C
  });

  // Dynamic Battery State
  const [state, setState] = useState<BatteryState>({
    measuredVoltage: 48.1,
    bmsVoltage: 48.0,
    remainingCapacityAh: 10,
    socPercentage: 50,
    currentAmps: 0
  });

  // Kalman Filter Instance (persistent via Ref)
  const kFilter = useRef(new KalmanFilter(0.005, 5.0, 50));
  const [filteredSOC, setFilteredSOC] = useState<number>(50);
  const [rawSOC, setRawSOC] = useState<number>(50);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState<boolean>(false);

  // Derived Values
  const totalEnergyWh = useMemo(() => 
    config.totalCapacityAh * config.nominalCellVoltage * config.seriesCount, 
  [config.totalCapacityAh, config.nominalCellVoltage, config.seriesCount]);

  const ocvVoltage = useMemo(() => 
    estimateOCV(state.measuredVoltage, state.currentAmps, config.seriesCount, config.internalResistanceMohm),
  [state.measuredVoltage, state.currentAmps, config.seriesCount, config.internalResistanceMohm]);

  const currentCellVoltage = state.measuredVoltage / config.seriesCount;
  const ocvCellVoltage = ocvVoltage / config.seriesCount;

  // Run Kalman filter loop
  useEffect(() => {
    const calculatedRawSOC = getSOCFromVoltage(ocvCellVoltage, config.chemistry);
    setRawSOC(calculatedRawSOC);

    const timer = setInterval(() => {
      setFilteredSOC(prev => {
        const next = kFilter.current.update(calculatedRawSOC);
        // Sync remaining capacity with filtered SOC
        setState(s => ({ ...s, socPercentage: next, remainingCapacityAh: (next / 100) * config.totalCapacityAh }));
        return next;
      });
    }, 100);

    return () => clearInterval(timer);
  }, [ocvCellVoltage, config.chemistry, config.totalCapacityAh]);

  // Logic Handlers
  const calculateSOCFromVoltage = useCallback(() => {
    const soc = getSOCFromVoltage(ocvCellVoltage, config.chemistry);
    kFilter.current.setState(soc); // Force filter to sync immediately
    setFilteredSOC(soc);
    setState(prev => ({ 
      ...prev, 
      socPercentage: soc,
      remainingCapacityAh: (soc / 100) * config.totalCapacityAh
    }));
  }, [ocvCellVoltage, config]);

  const calculateVoltageFromSOC = useCallback(() => {
    const cellV = getVoltageFromSOC(state.socPercentage, config.chemistry);
    setState(prev => ({ 
      ...prev, 
      measuredVoltage: cellV * config.seriesCount - (state.currentAmps * (config.internalResistanceMohm / 1000) * config.seriesCount),
      remainingCapacityAh: (state.socPercentage / 100) * config.totalCapacityAh
    }));
  }, [state.socPercentage, config, state.currentAmps]);

  const handleChemistryChange = (chem: BatteryChemistry) => {
    const defaults = CHEMISTRY_DEFAULTS[chem];
    setConfig(prev => ({
      ...prev,
      chemistry: chem,
      nominalCellVoltage: defaults.nominal,
      maxCellVoltage: defaults.max,
      minCellVoltage: defaults.min
    }));
  };

  const fetchInsights = useCallback(async () => {
    setIsAiLoading(true);
    const insights = await getBatteryInsights(
      config.chemistry,
      state.measuredVoltage,
      state.socPercentage,
      config.seriesCount,
      state.bmsVoltage,
      config.totalCapacityAh,
      config.chargeRateC
    );
    setAiInsights(insights || 'No insights available.');
    setIsAiLoading(false);
  }, [config, state]);

  const chartData = useMemo(() => {
    return SOC_MAPS[config.chemistry].map(point => ({
      soc: point.soc,
      voltage: parseFloat((point.v * config.seriesCount).toFixed(2)),
      cellVoltage: parseFloat(point.v.toFixed(3))
    })).sort((a, b) => a.soc - b.soc);
  }, [config.chemistry, config.seriesCount]);

  return (
    <div className="min-h-screen p-4 md:p-8 max-w-7xl mx-auto space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-slate-700 pb-6">
        <div>
          <h1 className="text-3xl font-bold flex items-center gap-2 text-blue-400">
            <Zap className="fill-blue-400" /> VoltSage <span className="text-xs bg-blue-500/20 text-blue-400 px-2 py-0.5 rounded-full border border-blue-500/30 uppercase tracking-tighter ml-2">Advanced</span>
          </h1>
          <p className="text-slate-400 mt-1 uppercase text-xs tracking-[0.2em] font-medium">Precision Kalman-Filtered SOC Estimator</p>
        </div>
        <div className="flex items-center gap-3">
          <button 
            onClick={fetchInsights}
            disabled={isAiLoading}
            className="flex items-center gap-2 bg-blue-600 hover:bg-blue-500 transition-all px-5 py-2.5 rounded-xl font-semibold text-sm disabled:opacity-50 shadow-lg shadow-blue-900/20 active:scale-95"
          >
            {isAiLoading ? <RefreshCw className="animate-spin w-4 h-4" /> : <Activity className="w-4 h-4" />}
            Analyze with Gemini
          </button>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* LEFT COLUMN: Inputs */}
        <div className="lg:col-span-4 space-y-6">
          {/* Configuration Card */}
          <section className="bg-slate-800/50 backdrop-blur-sm rounded-2xl p-6 border border-slate-700 shadow-xl">
            <div className="flex items-center justify-between mb-6">
              <div className="flex items-center gap-2 text-blue-400 font-bold uppercase text-xs tracking-wider">
                <Settings size={16} /> Configuration
              </div>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Battery Chemistry</label>
                <select 
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 transition-all text-sm appearance-none cursor-pointer"
                  value={config.chemistry}
                  onChange={(e) => handleChemistryChange(e.target.value as BatteryChemistry)}
                >
                  {Object.values(BatteryChemistry).map(c => (
                    <option key={c} value={c}>{c}</option>
                  ))}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Cell Count (S)</label>
                  <input 
                    type="number" 
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500"
                    value={config.seriesCount}
                    onChange={(e) => setConfig(prev => ({ ...prev, seriesCount: Math.max(1, parseInt(e.target.value) || 1) }))}
                  />
                </div>
                <div>
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">IR (mΩ/cell)</label>
                  <input 
                    type="number" step="0.1"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono"
                    value={config.internalResistanceMohm}
                    onChange={(e) => setConfig(prev => ({ ...prev, internalResistanceMohm: parseFloat(e.target.value) || 0 }))}
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Total Cap (Ah)</label>
                  <input 
                    type="number" step="0.1"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono"
                    value={config.totalCapacityAh}
                    onChange={(e) => setConfig(prev => ({ ...prev, totalCapacityAh: parseFloat(e.target.value) || 0 }))}
                  />
                </div>
                <div>
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Charge Rate (C)</label>
                  <input 
                    type="number" step="0.01" min="0.01"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono text-blue-400"
                    value={config.chargeRateC}
                    onChange={(e) => setConfig(prev => ({ ...prev, chargeRateC: parseFloat(e.target.value) || 0.01 }))}
                  />
                </div>
              </div>

              <div>
                <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Load Current (A)</label>
                <input 
                  type="number" step="0.1"
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono text-amber-400"
                  value={state.currentAmps}
                  placeholder="+"
                  onChange={(e) => setState(prev => ({ ...prev, currentAmps: parseFloat(e.target.value) || 0 }))}
                />
              </div>
            </div>
          </section>

          {/* Measurements Card */}
          <section className="bg-slate-800/50 backdrop-blur-sm rounded-2xl p-6 border border-slate-700 shadow-xl">
            <div className="flex items-center gap-2 mb-6 text-emerald-400 font-bold uppercase text-xs tracking-wider">
              <Battery size={16} /> Measurements
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Measured Pack Voltage</label>
                <div className="flex gap-2">
                  <input 
                    type="number" step="0.01"
                    className="flex-1 bg-slate-900 border border-slate-700 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-emerald-500 text-lg font-mono text-emerald-400"
                    value={state.measuredVoltage}
                    onChange={(e) => setState(prev => ({ ...prev, measuredVoltage: parseFloat(e.target.value) || 0 }))}
                  />
                  <button 
                    onClick={calculateSOCFromVoltage}
                    title="Estimate SOC from Voltage"
                    className="bg-emerald-600/20 hover:bg-emerald-600/30 text-emerald-400 p-3 rounded-xl transition-all border border-emerald-600/30 active:scale-95"
                  >
                    <ArrowRightLeft size={18} />
                  </button>
                </div>
                <div className="mt-2 text-[10px] text-slate-500 flex justify-between px-1">
                  <span>OCV Estimate: <span className="text-emerald-500/80">{ocvVoltage.toFixed(2)}V</span></span>
                  <span>Droop: <span className="text-amber-500/80">{(ocvVoltage - state.measuredVoltage).toFixed(2)}V</span></span>
                </div>
              </div>

              <div className="pt-4 border-t border-slate-700">
                <div className="flex justify-between items-center mb-2">
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold ml-1">Filtered SOC (%)</label>
                  <div className="flex items-center gap-1 text-[10px] text-blue-400 font-bold animate-pulse">
                    <Waves size={10} /> KALMAN ACTIVE
                  </div>
                </div>
                <div className="flex gap-2 items-center">
                  <div className="relative flex-1">
                    <input 
                      type="range" min="0" max="100" step="0.1"
                      className="w-full h-1.5 bg-slate-900 rounded-lg appearance-none cursor-pointer accent-blue-500"
                      value={state.socPercentage}
                      onChange={(e) => {
                        const val = parseFloat(e.target.value);
                        kFilter.current.setState(val);
                        setState(prev => ({ ...prev, socPercentage: val }));
