export enum BatteryChemistry {
  LI_ION = 'Li-ion (NMC/NCA)',
  LIFEPO4 = 'LiFePO4 (LFP)',
  LIPO = 'Li-Polymer'
}

export type CapacityUnit = 'Ah' | 'mAh';
export type EnergyUnit = 'Wh' | 'kWh';

export interface BatteryConfig {
  chemistry: BatteryChemistry;
  seriesCount: number;
  totalCapacityAh: number;
  nominalCellVoltage: number;
  maxCellVoltage: number;
  minCellVoltage: number;
  chargeRateC: number; // Charging rate in C-rate (e.g., 0.5 for 0.5C)
}

export interface BatteryState {
  measuredVoltage: number;
  bmsVoltage: number;
  remainingCapacityAh: number;
  socPercentage: number;
  currentAmps: number; // Current flow: positive for discharge, negative for charge
}

export interface CalculationResult {
  estimatedSOC: number;
