            <div className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700/50 shadow-lg relative overflow-hidden">
              <div className="text-slate-500 text-[10px] uppercase font-bold tracking-widest mb-1">System Status</div>
              <div className="text-3xl font-mono font-bold text-amber-400">{state.socPercentage.toFixed(1)}%</div>
              <div className="w-full bg-slate-900/50 h-1.5 rounded-full mt-3 border border-slate-700/50 overflow-hidden">
                <div className="h-full bg-amber-400" style={{ width: `${state.socPercentage}%` }} />
              </div>
            </div>
          </div>

          <div className="space-y-6">
            <section className="bg-slate-800/50 rounded-2xl p-6 border border-slate-700 shadow-xl">
              <h2 className="text-sm font-bold uppercase tracking-widest mb-6 flex items-center gap-2 text-slate-300">
                <Activity className="text-blue-400" size={16} /> Discharge Profile
              </h2>
              <div className="h-[280px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={chartData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                    <defs>
                      <linearGradient id="curveGrad" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.2}/>
                        <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
                    <XAxis dataKey="soc" hide />
                    <YAxis stroke="#475569" tick={{ fontSize: 10 }} domain={['auto', 'auto']} />
                    <Tooltip 
                      contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155', borderRadius: '12px' }}
                      itemStyle={{ color: '#60a5fa', fontSize: '12px' }}
                    />
                    <Area type="monotone" dataKey="voltage" stroke="#3b82f6" strokeWidth={2} fill="url(#curveGrad)" />
                    <ReferenceLine x={state.socPercentage} stroke="#fbbf24" strokeWidth={2} strokeDasharray="5 5" />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
              <div className="flex justify-between text-[10px] text-slate-500 font-mono mt-2 uppercase tracking-tighter">
                <span>Empty (0%)</span>
                <span>Volts (V)</span>
                <span>Full (100%)</span>
              </div>
            </section>

            <section className={`bg-slate-800/50 rounded-2xl p-6 border border-slate-700 shadow-xl transition-all ${aiInsights ? 'opacity-100' : 'opacity-40 cursor-not-allowed'}`}>
              <h2 className="text-sm font-bold uppercase tracking-widest mb-4 flex items-center gap-2 text-slate-300">
                <Zap className="text-amber-400" size={16} /> Engineer Insights
              </h2>
              {aiInsights ? (
                <div className="text-xs text-slate-300 leading-relaxed whitespace-pre-line max-h-[300px] overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-slate-700">
                  {aiInsights}
                </div>
              ) : (
                <div className="flex flex-col items-center justify-center h-[200px] text-center space-y-3">
                  <Activity className="text-slate-600 animate-pulse" size={32} />
                  <p className="text-xs text-slate-500 max-w-[220px]">Run analysis to generate professional battery health assessment.</p>
                </div>
              )}
            </section>
          </div>
        </div>
      </div>

      <footer className="text-center text-slate-600 text-[10px] uppercase tracking-widest pt-8 pb-4">
        Lithium Calculator By Han &bull; 2024
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { 
  Zap, 
  Battery, 
  Activity, 
  Settings, 
  RefreshCw,
  ArrowRightLeft,
  ShieldCheck,
  RotateCcw,
  LayoutDashboard,
  FileUp,
  CheckCircle2,
  AlertCircle
} from 'lucide-react';
import { 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  AreaChart,
  Area,
  ReferenceLine
} from 'recharts';
import { BatteryChemistry, BatteryConfig, BatteryState, CapacityUnit, EnergyUnit } from './types';
import { CHEMISTRY_DEFAULTS, SOC_MAPS } from './constants';
import { getSOCFromVoltage, getVoltageFromSOC } from './utils';
import { getBatteryInsights } from './geminiService';

const INITIAL_CONFIG: BatteryConfig = {
  chemistry: BatteryChemistry.LI_ION,
  seriesCount: 13, 
  totalCapacityAh: 20,
  nominalCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LI_ION].nominal,
  maxCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LI_ION].max,
  minCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LI_ION].min,
  chargeRateC: 0.5
};

const INITIAL_STATE: BatteryState = {
  measuredVoltage: 48.1,
  bmsVoltage: 48.0,
  remainingCapacityAh: 10,
  socPercentage: 50,
  currentAmps: 0
};

const App: React.FC = () => {
  const [config, setConfig] = useState<BatteryConfig>(INITIAL_CONFIG);
  const [state, setState] = useState<BatteryState>(INITIAL_STATE);
  const [capacityUnit, setCapacityUnit] = useState<CapacityUnit>('Ah');
  const [energyUnit, setEnergyUnit] = useState<EnergyUnit>('Wh');
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState<boolean>(false);
  const [uploadStatus, setUploadStatus] = useState<{ type: 'success' | 'error' | 'idle', message: string }>({ type: 'idle', message: '' });

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Unit Conversion Helpers
  const capacityToDisplay = (ah: number) => capacityUnit === 'mAh' ? ah * 1000 : ah;
  const displayToCapacity = (val: number) => capacityUnit === 'mAh' ? val / 1000 : val;
  const energyToDisplay = (wh: number) => energyUnit === 'kWh' ? wh / 1000 : wh;
  const displayToEnergy = (val: number) => energyUnit === 'kWh' ? val * 1000 : val;

  // Derived Values
  const totalEnergyWh = useMemo(() => 
    config.totalCapacityAh * config.nominalCellVoltage * config.seriesCount, 
  [config.totalCapacityAh, config.nominalCellVoltage, config.seriesCount]);

  const currentCellVoltage = state.measuredVoltage / config.seriesCount;

  // Automated SOC sync from voltage (only if not manually overriding or if we want it strictly linked)
  // We'll keep this but allow the manual input to trigger updates
  useEffect(() => {
    // Optional: Auto-sync logic if needed
  }, [state.measuredVoltage, config.chemistry, config.seriesCount, config.totalCapacityAh]);

  const handleReset = useCallback(() => {
    setConfig(INITIAL_CONFIG);
    setState(INITIAL_STATE);
    setCapacityUnit('Ah');
    setEnergyUnit('Wh');
    setAiInsights('');
    setUploadStatus({ type: 'idle', message: '' });
  }, []);

  const updateFromVoltage = useCallback((voltage: number) => {
    const cellV = voltage / config.seriesCount;
    const soc = getSOCFromVoltage(cellV, config.chemistry);
    setState(prev => ({
      ...prev,
      measuredVoltage: voltage,
      socPercentage: soc,
      remainingCapacityAh: (soc / 100) * config.totalCapacityAh
    }));
  }, [config.seriesCount, config.chemistry, config.totalCapacityAh]);

  const calculateVoltageFromSOC = useCallback((soc: number) => {
    const cellV = getVoltageFromSOC(soc, config.chemistry);
    setState(prev => ({ 
      ...prev, 
      socPercentage: soc,
      measuredVoltage: parseFloat((cellV * config.seriesCount).toFixed(2)),
      remainingCapacityAh: (soc / 100) * config.totalCapacityAh
    }));
  }, [config.chemistry, config.seriesCount, config.totalCapacityAh]);

  const handleChemistryChange = (chem: BatteryChemistry) => {
    const defaults = CHEMISTRY_DEFAULTS[chem];
    setConfig(prev => ({
      ...prev,
      chemistry: chem,
      nominalCellVoltage: defaults.nominal,
      maxCellVoltage: defaults.max,
      minCellVoltage: defaults.min
    }));
  };

  const fetchInsights = useCallback(async () => {
    setIsAiLoading(true);
    const insights = await getBatteryInsights(
      config.chemistry,
      state.measuredVoltage,
      state.socPercentage,
      config.seriesCount,
      state.bmsVoltage,
      config.totalCapacityAh,
      config.chargeRateC
    );
    setAiInsights(insights || 'No insights available.');
    setIsAiLoading(false);
  }, [config, state]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (!text) return;

      try {
        const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
        if (lines.length < 2) throw new Error("File too short");

        const headers = lines[0].toLowerCase().split(',').map(h => h.trim());
        const lastData = lines[lines.length - 1].split(',').map(d => d.trim());

        // Simple heuristic for column mapping
        const getVal = (keywords: string[]) => {
          const index = headers.findIndex(h => keywords.some(k => h.includes(k)));
          return index !== -1 ? parseFloat(lastData[index]) : null;
        };

        const importedVoltage = getVal(['volt', 'v_pack', 'pack_v', 'total_v']);
        const importedSoc = getVal(['soc', 'percent', 'cap_%', 'capacity_%']);
        const importedCurrent = getVal(['curr', 'amp', 'i_pack']);
        const importedCapacity = getVal(['rem', 'capacity_ah', 'ah_rem', 'left_ah']);
        const importedBmsV = getVal(['bms_v', 'internal_v', 'cell_sum']);

        if (importedVoltage === null && importedSoc === null) {
          throw new Error("Could not find Voltage or SOC columns");
        }

        setState(prev => {
          const newState = { ...prev };
          if (importedVoltage !== null) newState.measuredVoltage = importedVoltage;
          if (importedBmsV !== null) newState.bmsVoltage = importedBmsV;
          if (importedCurrent !== null) newState.currentAmps = importedCurrent;

          if (importedSoc !== null) {
            newState.socPercentage = importedSoc;
            newState.remainingCapacityAh = (importedSoc / 100) * config.totalCapacityAh;
          } else if (importedVoltage !== null) {
            const soc = getSOCFromVoltage(importedVoltage / config.seriesCount, config.chemistry);
            newState.socPercentage = soc;
            newState.remainingCapacityAh = (soc / 100) * config.totalCapacityAh;
          }

          if (importedCapacity !== null) {
            newState.remainingCapacityAh = importedCapacity;
          }

          return newState;
        });

        setUploadStatus({ type: 'success', message: `Imported data from ${file.name}` });
      } catch (err) {
        setUploadStatus({ type: 'error', message: `Error: ${err instanceof Error ? err.message : 'Invalid CSV format'}` });
      }
    };
    reader.readAsText(file);
    // Reset file input value so same file can be uploaded again if needed
    event.target.value = '';
  };

  const chartData = useMemo(() => {
    return SOC_MAPS[config.chemistry].map(point => ({
      soc: point.soc,
      voltage: parseFloat((point.v * config.seriesCount).toFixed(2)),
      cellVoltage: parseFloat(point.v.toFixed(3))
    })).sort((a, b) => a.soc - b.soc);
  }, [config.chemistry, config.seriesCount]);

  const UnitToggle = ({ value, options, onChange }: { value: string, options: string[], onChange: (v: any) => void }) => (
    <div className="flex bg-slate-900 rounded-lg p-0.5 border border-slate-700 h-6">
      {options.map(opt => (
        <button
          key={opt}
          onClick={() => onChange(opt)}
          className={`px-2 text-[8px] font-bold uppercase tracking-widest rounded transition-all ${value === opt ? 'bg-blue-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}
        >
          {opt}
        </button>
      ))}
    </div>
  );

  return (
    <div className="min-h-screen p-4 md:p-8 max-w-7xl mx-auto space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-slate-700 pb-6">
        <div>
          <h1 className="text-3xl font-bold flex items-center gap-2 text-blue-400">
            <Zap className="fill-blue-400" /> Lithium Calculator By Han
          </h1>
          <p className="text-slate-400 mt-1 uppercase text-xs tracking-[0.2em] font-medium">Battery Voltage & SOC Calculator</p>
        </div>
        <div className="flex items-center gap-3">
          <input 
            type="file" 
            accept=".csv" 
            className="hidden" 
            ref={fileInputRef} 
            onChange={handleFileUpload} 
          />
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 transition-all px-4 py-2.5 rounded-xl font-semibold text-sm active:scale-95 group"
          >
            <FileUp className="w-4 h-4 text-emerald-400 group-hover:scale-110 transition-transform" />
            Upload BMS CSV
          </button>
          <button 
            onClick={handleReset}
            className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 transition-all px-4 py-2.5 rounded-xl font-semibold text-sm active:scale-95"
          >
            <RotateCcw className="w-4 h-4" />
            Reset
          </button>
          <button 
            onClick={fetchInsights}
            disabled={isAiLoading}
            className="flex items-center gap-2 bg-blue-600 hover:bg-blue-500 transition-all px-5 py-2.5 rounded-xl font-semibold text-sm disabled:opacity-50 shadow-lg shadow-blue-900/20 active:scale-95"
          >
            {isAiLoading ? <RefreshCw className="animate-spin w-4 h-4" /> : <Activity className="w-4 h-4" />}
            Analyze with Gemini
          </button>
        </div>
      </header>

      {uploadStatus.type !== 'idle' && (
        <div className={`flex items-center gap-3 px-4 py-3 rounded-xl border ${uploadStatus.type === 'success' ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' : 'bg-red-500/10 border-red-500/30 text-red-400'} animate-in slide-in-from-top-4 duration-300`}>
          {uploadStatus.type === 'success' ? <CheckCircle2 size={18} /> : <AlertCircle size={18} />}
          <span className="text-sm font-medium">{uploadStatus.message}</span>
          <button onClick={() => setUploadStatus({ type: 'idle', message: '' })} className="ml-auto opacity-50 hover:opacity-100">✕</button>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <div className="lg:col-span-4 space-y-6">
          <section className="bg-slate-800/50 backdrop-blur-sm rounded-2xl p-6 border border-slate-700 shadow-xl">
            <div className="flex items-center gap-2 text-blue-400 font-bold uppercase text-xs tracking-wider mb-6">
              <Settings size={16} /> Configuration
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Battery Chemistry</label>
                <select 
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 transition-all text-sm cursor-pointer"
                  value={config.chemistry}
                  onChange={(e) => handleChemistryChange(e.target.value as BatteryChemistry)}
                >
                  {Object.values(BatteryChemistry).map(c => (
                    <option key={c} value={c}>{c}</option>
                  ))}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Cell Count (S)</label>
                  <input 
                    type="number" 
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500"
                    value={config.seriesCount}
                    onChange={(e) => setConfig(prev => ({ ...prev, seriesCount: Math.max(1, parseInt(e.target.value) || 1) }))}
                  />
                </div>
                <div>
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Charge Rate (C)</label>
                    <input 
                    type="number" step="0.01" min="0.01"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono text-blue-400"
                    value={config.chargeRateC}
                    onChange={(e) => setConfig(prev => ({ ...prev, chargeRateC: parseFloat(e.target.value) || 0.01 }))}
                    />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <div className="flex justify-between items-center mb-1.5 ml-1">
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold">Total Capacity</label>
                    <UnitToggle value={capacityUnit} options={['Ah', 'mAh']} onChange={setCapacityUnit} />
                  </div>
                  <input 
                    type="number" step="0.1"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono"
                    value={capacityToDisplay(config.totalCapacityAh).toFixed(capacityUnit === 'mAh' ? 0 : 2)}
                    onChange={(e) => setConfig(prev => ({ ...prev, totalCapacityAh: displayToCapacity(parseFloat(e.target.value) || 0) }))}
                  />
                </div>
                <div>
                  <div className="flex justify-between items-center mb-1.5 ml-1">
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold">Total Energy</label>
                    <UnitToggle value={energyUnit} options={['Wh', 'kWh']} onChange={setEnergyUnit} />
                  </div>
                  <input 
                    type="number" step="0.01"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono"
                    value={energyToDisplay(totalEnergyWh).toFixed(energyUnit === 'kWh' ? 3 : 1)}
                    readOnly
                  />
                </div>
              </div>
            </div>
          </section>

          <section className="bg-slate-800/50 backdrop-blur-sm rounded-2xl p-6 border border-slate-700 shadow-xl">
            <div className="flex items-center justify-between mb-6">
              <div className="flex items-center gap-2 text-emerald-400 font-bold uppercase text-xs tracking-wider">
                <Battery size={16} /> Measurements
              </div>
              {uploadStatus.type === 'success' && (
                <div className="flex items-center gap-1.5 text-[8px] font-bold text-emerald-400 uppercase tracking-tighter bg-emerald-500/10 px-2 py-0.5 rounded-full border border-emerald-500/20">
                  <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                  Live Data
                </div>
              )}
            </div>

            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Pack Voltage</label>
                  <input 
                    type="number" step="0.01"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 outline-none focus:ring-2 focus:ring-emerald-500 text-sm font-mono text-emerald-400"
                    value={state.measuredVoltage}
                    onChange={(e) => updateFromVoltage(parseFloat(e.target.value) || 0)}
                  />
                </div>
                <div>
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">BMS Voltage</label>
                  <input 
                    type="number" step="0.01"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 outline-none focus:ring-2 focus:ring-blue-500 text-sm font-mono text-blue-400"
                    value={state.bmsVoltage}
                    onChange={(e) => setState(prev => ({ ...prev, bmsVoltage: parseFloat(e.target.value) || 0 }))}
                  />
                </div>
              </div>

              <div>
                <div className="flex justify-between items-center mb-2">
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold ml-1">SOC Percentage (%)</label>
                  <span className="text-xs font-mono font-bold text-emerald-400">{state.socPercentage.toFixed(1)}%</span>
                </div>
                <input 
                  type="range" min="0" max="100" step="0.1"
                  className="w-full h-1.5 bg-slate-900 rounded-lg appearance-none cursor-pointer accent-emerald-500"
                  value={state.socPercentage}
                  onChange={(e) => calculateVoltageFromSOC(parseFloat(e.target.value))}
                />
              </div>

              <div>
                <div className="flex justify-between items-center mb-1.5 ml-1">
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold">Remaining Capacity</label>
                  <UnitToggle value={capacityUnit} options={['Ah', 'mAh']} onChange={setCapacityUnit} />
                </div>
                <input 
                  type="number" step="0.1"
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none font-mono"
                  value={capacityToDisplay(state.remainingCapacityAh).toFixed(capacityUnit === 'mAh' ? 0 : 2)}
                  onChange={(e) => {
                    const val = parseFloat(e.target.value) || 0;
                    const ah = displayToCapacity(val);
                    const soc = (ah / config.totalCapacityAh) * 100;
                    setState(prev => ({ 
                      ...prev, 
                      remainingCapacityAh: ah, 
                      socPercentage: soc, 
                      measuredVoltage: parseFloat((getVoltageFromSOC(soc, config.chemistry) * config.seriesCount).toFixed(2)) 
                    }));
                  }}
                />
              </div>
            </div>
          </section>
        </div>

        <div className="lg:col-span-8 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700/50 shadow-lg relative overflow-hidden">
              <div className="text-slate-500 text-[10px] uppercase font-bold tracking-widest mb-1">Cell Voltage</div>
              <div className="text-3xl font-mono font-bold text-emerald-400">{currentCellVoltage.toFixed(3)}V</div>
              <Activity className="absolute top-4 right-4 text-slate-700 opacity-20" size={48} />
            </div>

            <div className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700/50 shadow-lg relative overflow-hidden">
              <div className="flex justify-between items-center mb-1">
                  <div className="text-slate-500 text-[10px] uppercase font-bold tracking-widest">Rem. Energy</div>
                  <UnitToggle value={energyUnit} options={['Wh', 'kWh']} onChange={setEnergyUnit} />
              </div>
              <div className="text-3xl font-mono font-bold text-blue-400">
                  {energyToDisplay((state.socPercentage / 100) * totalEnergyWh).toFixed(energyUnit === 'kWh' ? 3 : 1)}
                  <span className="text-sm ml-1 font-normal opacity-50">{energyUnit}</span>
              </div>
              <LayoutDashboard className="absolute top-4 right-4 text-slate-700 opacity-20" size={48} />
            </div>

            <div className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700/50 shadow-lg relative overflow-hidden">
              <div className="text-slate-500 text-[10px] uppercase font-bold tracking-widest mb-1">System Status</div>
              <div className="text-3xl font-mono font-bold text-amber-400">{state.socPercentage.toFixed(1)}%</div>
              <div className="w-full bg-slate-900/50 h-1.5 rounded-full mt-3 border border-slate-700/50 overflow-hidden">
                <div 
                  className={`h-full transition-all duration-500 ${state.socPercentage > 20 ? 'bg-amber-400' : 'bg-red-500 animate-pulse'}`} 
                  style={{ width: `${state.socPercentage}%` }} 
                />
              </div>
            </div>
          </div>

          <div className="space-y-6">
            <section className="bg-slate-800/50 rounded-2xl p-6 border border-slate-700 shadow-xl">
              <h2 className="text-sm font-bold uppercase tracking-widest mb-6 flex items-center gap-2 text-slate-300">
                <Activity className="text-blue-400" size={16} /> Discharge Profile
              </h2>
              <div className="h-[280px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={chartData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                    <defs>
                      <linearGradient id="curveGrad" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.2}/>
                        <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
                    <XAxis dataKey="soc" hide />
                    <YAxis stroke="#475569" tick={{ fontSize: 10 }} domain={['auto', 'auto']} />
                    <Tooltip 
                      contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155', borderRadius: '12px' }}
                      itemStyle={{ color: '#60a5fa', fontSize: '12px' }}
                    />
                    <Area type="monotone" dataKey="voltage" stroke="#3b82f6" strokeWidth={2} fill="url(#curveGrad)" />
                    <ReferenceLine x={state.socPercentage} stroke="#fbbf24" strokeWidth={2} strokeDasharray="5 5" />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
              <div className="flex justify-between text-[10px] text-slate-500 font-mono mt-2 uppercase tracking-tighter">
                <span>Empty (0%)</span>
                <span>Volts (V)</span>
                <span>Full (100%)</span>
              </div>
            </section>

            <section className={`bg-slate-800/50 rounded-2xl p-6 border border-slate-700 shadow-xl transition-all ${aiInsights ? 'opacity-100' : 'opacity-40 cursor-not-allowed'}`}>
              <h2 className="text-sm font-bold uppercase tracking-widest mb-4 flex items-center gap-2 text-slate-300">
                <Zap className="text-amber-400" size={16} /> Engineer Insights
              </h2>
              {aiInsights ? (
                <div className="text-xs text-slate-300 leading-relaxed whitespace-pre-line max-h-[300px] overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-slate-700">
                  {aiInsights}
                </div>
              ) : (
                <div className="flex flex-col items-center justify-center h-[200px] text-center space-y-3">
                  <Activity className="text-slate-600 animate-pulse" size={32} />
                  <p className="text-xs text-slate-500 max-w-[220px]">Run analysis to generate professional battery health assessment.</p>
                </div>
              )}
            </section>
          </div>
        </div>
      </div>

      <footer className="text-center text-slate-600 text-[10px] uppercase tracking-widest pt-8 pb-4">
        Lithium Calculator By Han &bull; 2024
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { 
  Zap, 
  Battery, 
  Activity, 
  Settings, 
  RefreshCw,
  ArrowRightLeft,
  ShieldCheck,
  RotateCcw,
  LayoutDashboard,
  FileUp,
  CheckCircle2,
  AlertCircle
} from 'lucide-react';
import { 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  AreaChart,
  Area,
  ReferenceLine
} from 'recharts';
import { BatteryChemistry, BatteryConfig, BatteryState, CapacityUnit, EnergyUnit } from './types';
import { CHEMISTRY_DEFAULTS, SOC_MAPS } from './constants';
import { getSOCFromVoltage, getVoltageFromSOC } from './utils';
import { getBatteryInsights } from './geminiService';

const INITIAL_CONFIG: BatteryConfig = {
  chemistry: BatteryChemistry.LIFEPO4,
  seriesCount: 15, 
  totalCapacityAh: 100, // Common for 48V LFP packs
  nominalCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].nominal,
  maxCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].max,
  minCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].min,
  chargeRateC: 0.5
};

const INITIAL_STATE: BatteryState = {
  measuredVoltage: 49.5, // ~3.3V per cell, high plateau for LFP
  bmsVoltage: 49.5,
  remainingCapacityAh: 80,
  socPercentage: 80,
  currentAmps: 0
};

const App: React.FC = () => {
  const [config, setConfig] = useState<BatteryConfig>(INITIAL_CONFIG);
  const [state, setState] = useState<BatteryState>(INITIAL_STATE);
  const [capacityUnit, setCapacityUnit] = useState<CapacityUnit>('Ah');
  const [energyUnit, setEnergyUnit] = useState<EnergyUnit>('kWh'); // Default to kWh for larger 48V systems
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState<boolean>(false);
  const [uploadStatus, setUploadStatus] = useState<{ type: 'success' | 'error' | 'idle', message: string }>({ type: 'idle', message: '' });

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Unit Conversion Helpers
  const capacityToDisplay = (ah: number) => capacityUnit === 'mAh' ? ah * 1000 : ah;
  const displayToCapacity = (val: number) => capacityUnit === 'mAh' ? val / 1000 : val;
  const energyToDisplay = (wh: number) => energyUnit === 'kWh' ? wh / 1000 : wh;
  const displayToEnergy = (val: number) => energyUnit === 'kWh' ? val * 1000 : val;

  // Derived Values
  const totalEnergyWh = useMemo(() => 
    config.totalCapacityAh * config.nominalCellVoltage * config.seriesCount, 
  [config.totalCapacityAh, config.nominalCellVoltage, config.seriesCount]);

  const currentCellVoltage = state.measuredVoltage / config.seriesCount;

  const handleReset = useCallback(() => {
    setConfig(INITIAL_CONFIG);
    setState(INITIAL_STATE);
    setCapacityUnit('Ah');
    setEnergyUnit('kWh');
    setAiInsights('');
    setUploadStatus({ type: 'idle', message: '' });
  }, []);

  const updateFromVoltage = useCallback((voltage: number) => {
    const cellV = voltage / config.seriesCount;
    const soc = getSOCFromVoltage(cellV, config.chemistry);
    setState(prev => ({
      ...prev,
      measuredVoltage: voltage,
      socPercentage: soc,
      remainingCapacityAh: (soc / 100) * config.totalCapacityAh
    }));
  }, [config.seriesCount, config.chemistry, config.totalCapacityAh]);

  const calculateVoltageFromSOC = useCallback((soc: number) => {
    const cellV = getVoltageFromSOC(soc, config.chemistry);
    setState(prev => ({ 
      ...prev, 
      socPercentage: soc,
      measuredVoltage: parseFloat((cellV * config.seriesCount).toFixed(2)),
      remainingCapacityAh: (soc / 100) * config.totalCapacityAh
    }));
  }, [config.chemistry, config.seriesCount, config.totalCapacityAh]);

  const handleChemistryChange = (chem: BatteryChemistry) => {
    const defaults = CHEMISTRY_DEFAULTS[chem];
    setConfig(prev => ({
      ...prev,
      chemistry: chem,
      nominalCellVoltage: defaults.nominal,
      maxCellVoltage: defaults.max,
      minCellVoltage: defaults.min
    }));
  };

  const fetchInsights = useCallback(async () => {
    setIsAiLoading(true);
    const insights = await getBatteryInsights(
      config.chemistry,
      state.measuredVoltage,
      state.socPercentage,
      config.seriesCount,
      state.bmsVoltage,
      config.totalCapacityAh,
      config.chargeRateC
    );
    setAiInsights(insights || 'No insights available.');
    setIsAiLoading(false);
  }, [config, state]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (!text) return;

      try {
        const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
        if (lines.length < 2) throw new Error("File too short");

        const headers = lines[0].toLowerCase().split(',').map(h => h.trim());
        const lastData = lines[lines.length - 1].split(',').map(d => d.trim());

        const getVal = (keywords: string[]) => {
          const index = headers.findIndex(h => keywords.some(k => h.includes(k)));
          return index !== -1 ? parseFloat(lastData[index]) : null;
        };

        const importedVoltage = getVal(['volt', 'v_pack', 'pack_v', 'total_v']);
        const importedSoc = getVal(['soc', 'percent', 'cap_%', 'capacity_%']);
        const importedCurrent = getVal(['curr', 'amp', 'i_pack']);
        const importedCapacity = getVal(['rem', 'capacity_ah', 'ah_rem', 'left_ah']);
        const importedBmsV = getVal(['bms_v', 'internal_v', 'cell_sum']);

        if (importedVoltage === null && importedSoc === null) {
          throw new Error("Could not find Voltage or SOC columns");
        }

        setState(prev => {
          const newState = { ...prev };
          if (importedVoltage !== null) newState.measuredVoltage = importedVoltage;
          if (importedBmsV !== null) newState.bmsVoltage = importedBmsV;
          if (importedCurrent !== null) newState.currentAmps = importedCurrent;

          if (importedSoc !== null) {
            newState.socPercentage = importedSoc;
            newState.remainingCapacityAh = (importedSoc / 100) * config.totalCapacityAh;
          } else if (importedVoltage !== null) {
            const soc = getSOCFromVoltage(importedVoltage / config.seriesCount, config.chemistry);
            newState.socPercentage = soc;
            newState.remainingCapacityAh = (soc / 100) * config.totalCapacityAh;
          }

          if (importedCapacity !== null) {
            newState.remainingCapacityAh = importedCapacity;
          }

          return newState;
        });

        setUploadStatus({ type: 'success', message: `Imported BMS data from ${file.name}` });
      } catch (err) {
        setUploadStatus({ type: 'error', message: `Error: ${err instanceof Error ? err.message : 'Invalid CSV format'}` });
      }
    };
    reader.readAsText(file);
    event.target.value = '';
  };

  const chartData = useMemo(() => {
    return SOC_MAPS[config.chemistry].map(point => ({
      soc: point.soc,
      voltage: parseFloat((point.v * config.seriesCount).toFixed(2)),
      cellVoltage: parseFloat(point.v.toFixed(3))
    })).sort((a, b) => a.soc - b.soc);
  }, [config.chemistry, config.seriesCount]);

  const UnitToggle = ({ value, options, onChange }: { value: string, options: string[], onChange: (v: any) => void }) => (
    <div className="flex bg-slate-900 rounded-lg p-0.5 border border-slate-700 h-6">
      {options.map(opt => (
        <button
          key={opt}
          onClick={() => onChange(opt)}
          className={`px-2 text-[8px] font-bold uppercase tracking-widest rounded transition-all ${value === opt ? 'bg-blue-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}
        >
          {opt}
        </button>
      ))}
    </div>
  );

  return (
    <div className="min-h-screen p-4 md:p-8 max-w-7xl mx-auto space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-slate-700 pb-6">
        <div>
          <h1 className="text-3xl font-bold flex items-center gap-2 text-blue-400">
            <Zap className="fill-blue-400" /> Lithium Calculator By Han
          </h1>
          <p className="text-slate-400 mt-1 uppercase text-xs tracking-[0.2em] font-medium">BMS LFP 15S 48V Precision Tool</p>
        </div>
        <div className="flex items-center gap-3">
          <input 
            type="file" 
            accept=".csv" 
            className="hidden" 
            ref={fileInputRef} 
            onChange={handleFileUpload} 
          />
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 transition-all px-4 py-2.5 rounded-xl font-semibold text-sm active:scale-95 group"
          >
            <FileUp className="w-4 h-4 text-emerald-400 group-hover:scale-110 transition-transform" />
            Sync BMS CSV
          </button>
          <button 
            onClick={handleReset}
            className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 transition-all px-4 py-2.5 rounded-xl font-semibold text-sm active:scale-95"
          >
            <RotateCcw className="w-4 h-4" />
            Reset
          </button>
          <button 
            onClick={fetchInsights}
            disabled={isAiLoading}
            className="flex items-center gap-2 bg-blue-600 hover:bg-blue-500 transition-all px-5 py-2.5 rounded-xl font-semibold text-sm disabled:opacity-50 shadow-lg shadow-blue-900/20 active:scale-95"
          >
            {isAiLoading ? <RefreshCw className="animate-spin w-4 h-4" /> : <Activity className="w-4 h-4" />}
            Analyze System
          </button>
        </div>
      </header>

      {uploadStatus.type !== 'idle' && (
        <div className={`flex items-center gap-3 px-4 py-3 rounded-xl border ${uploadStatus.type === 'success' ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' : 'bg-red-500/10 border-red-500/30 text-red-400'} animate-in slide-in-from-top-4 duration-300`}>
          {uploadStatus.type === 'success' ? <CheckCircle2 size={18} /> : <AlertCircle size={18} />}
          <span className="text-sm font-medium">{uploadStatus.message}</span>
          <button onClick={() => setUploadStatus({ type: 'idle', message: '' })} className="ml-auto opacity-50 hover:opacity-100">✕</button>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <div className="lg:col-span-4 space-y-6">
          <section className="bg-slate-800/50 backdrop-blur-sm rounded-2xl p-6 border border-slate-700 shadow-xl">
            <div className="flex items-center gap-2 text-blue-400 font-bold uppercase text-xs tracking-wider mb-6">
              <Settings size={16} /> Configuration
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Battery Chemistry</label>
                <select 
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 transition-all text-sm cursor-pointer"
                  value={config.chemistry}
                  onChange={(e) => handleChemistryChange(e.target.value as BatteryChemistry)}
                >
                  {Object.values(BatteryChemistry).map(c => (
                    <option key={c} value={c}>{c}</option>
                  ))}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Cell Count (S)</label>
                  <input 
                    type="number" 
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500"
                    value={config.seriesCount}
                    onChange={(e) => setConfig(prev => ({ ...prev, seriesCount: Math.max(1, parseInt(e.target.value) || 1) }))}
                  />
                </div>
                <div>
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Charge Rate (C)</label>
                    <input 
                    type="number" step="0.01" min="0.01"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono text-blue-400"
                    value={config.chargeRateC}
                    onChange={(e) => setConfig(prev => ({ ...prev, chargeRateC: parseFloat(e.target.value) || 0.01 }))}
                    />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <div className="flex justify-between items-center mb-1.5 ml-1">
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold">Total Capacity</label>
                    <UnitToggle value={capacityUnit} options={['Ah', 'mAh']} onChange={setCapacityUnit} />
                  </div>
                  <input 
                    type="number" step="0.1"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono"
                    value={capacityToDisplay(config.totalCapacityAh).toFixed(capacityUnit === 'mAh' ? 0 : 2)}
                    onChange={(e) => setConfig(prev => ({ ...prev, totalCapacityAh: displayToCapacity(parseFloat(e.target.value) || 0) }))}
                  />
                </div>
                <div>
                  <div className="flex justify-between items-center mb-1.5 ml-1">
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold">Total Energy</label>
                    <UnitToggle value={energyUnit} options={['Wh', 'kWh']} onChange={setEnergyUnit} />
                  </div>
                  <input 
                    type="number" step="0.01"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono"
                    value={energyToDisplay(totalEnergyWh).toFixed(energyUnit === 'kWh' ? 3 : 1)}
                    readOnly
                  />
                </div>
              </div>
            </div>
          </section>

          <section className="bg-slate-800/50 backdrop-blur-sm rounded-2xl p-6 border border-slate-700 shadow-xl">
            <div className="flex items-center justify-between mb-6">
              <div className="flex items-center gap-2 text-emerald-400 font-bold uppercase text-xs tracking-wider">
                <Battery size={16} /> Live Measurements
              </div>
              {uploadStatus.type === 'success' && (
                <div className="flex items-center gap-1.5 text-[8px] font-bold text-emerald-400 uppercase tracking-tighter bg-emerald-500/10 px-2 py-0.5 rounded-full border border-emerald-500/20">
                  <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                  BMS ACTIVE
                </div>
              )}
            </div>

            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Pack Voltage</label>
                  <input 
                    type="number" step="0.01"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 outline-none focus:ring-2 focus:ring-emerald-500 text-sm font-mono text-emerald-400"
                    value={state.measuredVoltage}
                    onChange={(e) => updateFromVoltage(parseFloat(e.target.value) || 0)}
                  />
                </div>
                <div>
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">BMS Voltage</label>
                  <input 
                    type="number" step="0.01"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 outline-none focus:ring-2 focus:ring-blue-500 text-sm font-mono text-blue-400"
                    value={state.bmsVoltage}
                    onChange={(e) => setState(prev => ({ ...prev, bmsVoltage: parseFloat(e.target.value) || 0 }))}
                  />
                </div>
              </div>

              <div>
                <div className="flex justify-between items-center mb-2">
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold ml-1">SOC Percentage (%)</label>
                  <span className="text-xs font-mono font-bold text-emerald-400">{state.socPercentage.toFixed(1)}%</span>
                </div>
                <input 
                  type="range" min="0" max="100" step="0.1"
                  className="w-full h-1.5 bg-slate-900 rounded-lg appearance-none cursor-pointer accent-emerald-500"
                  value={state.socPercentage}
                  onChange={(e) => calculateVoltageFromSOC(parseFloat(e.target.value))}
                />
              </div>

              <div>
                <div className="flex justify-between items-center mb-1.5 ml-1">
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold">Remaining Capacity</label>
                  <UnitToggle value={capacityUnit} options={['Ah', 'mAh']} onChange={setCapacityUnit} />
                </div>
                <input 
                  type="number" step="0.1"
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none font-mono"
                  value={capacityToDisplay(state.remainingCapacityAh).toFixed(capacityUnit === 'mAh' ? 0 : 2)}
                  onChange={(e) => {
                    const val = parseFloat(e.target.value) || 0;
                    const ah = displayToCapacity(val);
                    const soc = (ah / config.totalCapacityAh) * 100;
                    setState(prev => ({ 
                      ...prev, 
                      remainingCapacityAh: ah, 
                      socPercentage: soc, 
                      measuredVoltage: parseFloat((getVoltageFromSOC(soc, config.chemistry) * config.seriesCount).toFixed(2)) 
                    }));
                  }}
                />
              </div>
            </div>
          </section>
        </div>

        <div className="lg:col-span-8 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700/50 shadow-lg relative overflow-hidden">
              <div className="text-slate-500 text-[10px] uppercase font-bold tracking-widest mb-1">Cell Average</div>
              <div className="text-3xl font-mono font-bold text-emerald-400">{currentCellVoltage.toFixed(3)}V</div>
              <Activity className="absolute top-4 right-4 text-slate-700 opacity-20" size={48} />
            </div>

            <div className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700/50 shadow-lg relative overflow-hidden">
              <div className="flex justify-between items-center mb-1">
                  <div className="text-slate-500 text-[10px] uppercase font-bold tracking-widest">Rem. Energy</div>
                  <UnitToggle value={energyUnit} options={['Wh', 'kWh']} onChange={setEnergyUnit} />
              </div>
              <div className="text-3xl font-mono font-bold text-blue-400">
                  {energyToDisplay((state.socPercentage / 100) * totalEnergyWh).toFixed(energyUnit === 'kWh' ? 3 : 1)}
                  <span className="text-sm ml-1 font-normal opacity-50">{energyUnit}</span>
              </div>
              <LayoutDashboard className="absolute top-4 right-4 text-slate-700 opacity-20" size={48} />
            </div>

            <div className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700/50 shadow-lg relative overflow-hidden">
              <div className="text-slate-500 text-[10px] uppercase font-bold tracking-widest mb-1">System Health</div>
              <div className="text-3xl font-mono font-bold text-amber-400">{state.socPercentage.toFixed(1)}%</div>
              <div className="w-full bg-slate-900/50 h-1.5 rounded-full mt-3 border border-slate-700/50 overflow-hidden">
                <div 
                  className={`h-full transition-all duration-500 ${state.socPercentage > 20 ? 'bg-amber-400' : 'bg-red-500 animate-pulse'}`} 
                  style={{ width: `${state.socPercentage}%` }} 
                />
              </div>
            </div>
          </div>

          <div className="space-y-6">
            <section className="bg-slate-800/50 rounded-2xl p-6 border border-slate-700 shadow-xl">
              <h2 className="text-sm font-bold uppercase tracking-widest mb-6 flex items-center gap-2 text-slate-300">
                <Activity className="text-blue-400" size={16} /> Discharge Curve Profile
              </h2>
              <div className="h-[280px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={chartData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                    <defs>
                      <linearGradient id="curveGrad" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.2}/>
                        <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
                    <XAxis dataKey="soc" hide />
                    <YAxis stroke="#475569" tick={{ fontSize: 10 }} domain={['auto', 'auto']} />
                    <Tooltip 
                      contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155', borderRadius: '12px' }}
                      itemStyle={{ color: '#60a5fa', fontSize: '12px' }}
                    />
                    <Area type="monotone" dataKey="voltage" stroke="#3b82f6" strokeWidth={2} fill="url(#curveGrad)" />
                    <ReferenceLine x={state.socPercentage} stroke="#fbbf24" strokeWidth={2} strokeDasharray="5 5" />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
              <div className="flex justify-between text-[10px] text-slate-500 font-mono mt-2 uppercase tracking-tighter">
                <span>0% SOC</span>
                <span>System Voltage (V)</span>
                <span>100% SOC</span>
              </div>
            </section>

            <section className={`bg-slate-800/50 rounded-2xl p-6 border border-slate-700 shadow-xl transition-all ${aiInsights ? 'opacity-100' : 'opacity-40 cursor-not-allowed'}`}>
              <h2 className="text-sm font-bold uppercase tracking-widest mb-4 flex items-center gap-2 text-slate-300">
                <Zap className="text-amber-400" size={16} /> Engineer Insights
              </h2>
              {aiInsights ? (
                <div className="text-xs text-slate-300 leading-relaxed whitespace-pre-line max-h-[300px] overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-slate-700">
                  {aiInsights}
                </div>
              ) : (
                <div className="flex flex-col items-center justify-center h-[200px] text-center space-y-3">
                  <Activity className="text-slate-600 animate-pulse" size={32} />
                  <p className="text-xs text-slate-500 max-w-[220px]">Analysis will generate professional LFP 15S 48V system diagnostics.</p>
                </div>
              )}
            </section>
          </div>
        </div>
      </div>

      <footer className="text-center text-slate-600 text-[10px] uppercase tracking-widest pt-8 pb-4">
        Lithium Calculator By Han &bull; LFP 15S Specialty Config &bull; 2024
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { 
  Zap, 
  Battery, 
  Activity, 
  Settings, 
  RefreshCw,
  ArrowRightLeft,
  ShieldCheck,
  RotateCcw,
  LayoutDashboard,
  FileUp,
  CheckCircle2,
  AlertCircle
} from 'lucide-react';
import { 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  AreaChart,
  Area,
  ReferenceLine
} from 'recharts';
import { BatteryChemistry, BatteryConfig, BatteryState, CapacityUnit, EnergyUnit } from './types';
import { CHEMISTRY_DEFAULTS, SOC_MAPS } from './constants';
import { getSOCFromVoltage, getVoltageFromSOC } from './utils';
import { getBatteryInsights } from './geminiService';

const INITIAL_CONFIG: BatteryConfig = {
  chemistry: BatteryChemistry.LIFEPO4,
  seriesCount: 15, 
  totalCapacityAh: 100, // Common for 48V LFP packs
  nominalCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].nominal,
  maxCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].max,
  minCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].min,
  chargeRateC: 0.5
};

const INITIAL_STATE: BatteryState = {
  measuredVoltage: 49.5, // ~3.3V per cell, high plateau for LFP
  bmsVoltage: 49.5,
  remainingCapacityAh: 80,
  socPercentage: 80,
  currentAmps: 0
};

const App: React.FC = () => {
  const [config, setConfig] = useState<BatteryConfig>(INITIAL_CONFIG);
  const [state, setState] = useState<BatteryState>(INITIAL_STATE);
  const [capacityUnit, setCapacityUnit] = useState<CapacityUnit>('Ah');
  const [energyUnit, setEnergyUnit] = useState<EnergyUnit>('kWh'); // Default to kWh for larger 48V systems
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState<boolean>(false);
  const [uploadStatus, setUploadStatus] = useState<{ type: 'success' | 'error' | 'idle', message: string }>({ type: 'idle', message: '' });

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Unit Conversion Helpers
  const capacityToDisplay = (ah: number) => capacityUnit === 'mAh' ? ah * 1000 : ah;
  const displayToCapacity = (val: number) => capacityUnit === 'mAh' ? val / 1000 : val;
  const energyToDisplay = (wh: number) => energyUnit === 'kWh' ? wh / 1000 : wh;
  const displayToEnergy = (val: number) => energyUnit === 'kWh' ? val * 1000 : val;

  // Derived Values
  const totalEnergyWh = useMemo(() => 
    config.totalCapacityAh * config.nominalCellVoltage * config.seriesCount, 
  [config.totalCapacityAh, config.nominalCellVoltage, config.seriesCount]);

  const currentCellVoltage = state.measuredVoltage / config.seriesCount;

  const handleReset = useCallback(() => {
    setConfig(INITIAL_CONFIG);
    setState(INITIAL_STATE);
    setCapacityUnit('Ah');
    setEnergyUnit('kWh');
    setAiInsights('');
    setUploadStatus({ type: 'idle', message: '' });
  }, []);

  const updateFromVoltage = useCallback((voltage: number) => {
    const cellV = voltage / config.seriesCount;
    const soc = getSOCFromVoltage(cellV, config.chemistry);
    setState(prev => ({
      ...prev,
      measuredVoltage: voltage,
      socPercentage: soc,
      remainingCapacityAh: (soc / 100) * config.totalCapacityAh
    }));
  }, [config.seriesCount, config.chemistry, config.totalCapacityAh]);

  const calculateVoltageFromSOC = useCallback((soc: number) => {
    const safeSoc = Math.min(100, Math.max(0, soc));
    const cellV = getVoltageFromSOC(safeSoc, config.chemistry);
    setState(prev => ({ 
      ...prev, 
      socPercentage: safeSoc,
      measuredVoltage: parseFloat((cellV * config.seriesCount).toFixed(2)),
      remainingCapacityAh: (safeSoc / 100) * config.totalCapacityAh
    }));
  }, [config.chemistry, config.seriesCount, config.totalCapacityAh]);

  const handleChemistryChange = (chem: BatteryChemistry) => {
    const defaults = CHEMISTRY_DEFAULTS[chem];
    setConfig(prev => ({
      ...prev,
      chemistry: chem,
      nominalCellVoltage: defaults.nominal,
      maxCellVoltage: defaults.max,
      minCellVoltage: defaults.min
    }));
  };

  const fetchInsights = useCallback(async () => {
    setIsAiLoading(true);
    const insights = await getBatteryInsights(
      config.chemistry,
      state.measuredVoltage,
      state.socPercentage,
      config.seriesCount,
      state.bmsVoltage,
      config.totalCapacityAh,
      config.chargeRateC
    );
    setAiInsights(insights || 'No insights available.');
    setIsAiLoading(false);
  }, [config, state]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (!text) return;

      try {
        const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
        if (lines.length < 2) throw new Error("File too short");

        const headers = lines[0].toLowerCase().split(',').map(h => h.trim());
        const lastData = lines[lines.length - 1].split(',').map(d => d.trim());

        const getVal = (keywords: string[]) => {
          const index = headers.findIndex(h => keywords.some(k => h.includes(k)));
          return index !== -1 ? parseFloat(lastData[index]) : null;
        };

        const importedVoltage = getVal(['volt', 'v_pack', 'pack_v', 'total_v']);
        const importedSoc = getVal(['soc', 'percent', 'cap_%', 'capacity_%']);
        const importedCurrent = getVal(['curr', 'amp', 'i_pack']);
        const importedCapacity = getVal(['rem', 'capacity_ah', 'ah_rem', 'left_ah']);
        const importedBmsV = getVal(['bms_v', 'internal_v', 'cell_sum']);

        if (importedVoltage === null && importedSoc === null) {
          throw new Error("Could not find Voltage or SOC columns");
        }

        setState(prev => {
          const newState = { ...prev };
          if (importedVoltage !== null) newState.measuredVoltage = importedVoltage;
          if (importedBmsV !== null) newState.bmsVoltage = importedBmsV;
          if (importedCurrent !== null) newState.currentAmps = importedCurrent;

          if (importedSoc !== null) {
            newState.socPercentage = importedSoc;
            newState.remainingCapacityAh = (importedSoc / 100) * config.totalCapacityAh;
          } else if (importedVoltage !== null) {
            const soc = getSOCFromVoltage(importedVoltage / config.seriesCount, config.chemistry);
            newState.socPercentage = soc;
            newState.remainingCapacityAh = (soc / 100) * config.totalCapacityAh;
          }

          if (importedCapacity !== null) {
            newState.remainingCapacityAh = importedCapacity;
          }

          return newState;
        });

        setUploadStatus({ type: 'success', message: `Imported BMS data from ${file.name}` });
      } catch (err) {
        setUploadStatus({ type: 'error', message: `Error: ${err instanceof Error ? err.message : 'Invalid CSV format'}` });
      }
    };
    reader.readAsText(file);
    event.target.value = '';
  };

  const chartData = useMemo(() => {
    return SOC_MAPS[config.chemistry].map(point => ({
      soc: point.soc,
      voltage: parseFloat((point.v * config.seriesCount).toFixed(2)),
      cellVoltage: parseFloat(point.v.toFixed(3))
    })).sort((a, b) => a.soc - b.soc);
  }, [config.chemistry, config.seriesCount]);

  const UnitToggle = ({ value, options, onChange }: { value: string, options: string[], onChange: (v: any) => void }) => (
    <div className="flex bg-slate-900 rounded-lg p-0.5 border border-slate-700 h-6">
      {options.map(opt => (
        <button
          key={opt}
          onClick={() => onChange(opt)}
          className={`px-2 text-[8px] font-bold uppercase tracking-widest rounded transition-all ${value === opt ? 'bg-blue-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}
        >
          {opt}
        </button>
      ))}
    </div>
  );

  return (
    <div className="min-h-screen p-4 md:p-8 max-w-7xl mx-auto space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-slate-700 pb-6">
        <div>
          <h1 className="text-3xl font-bold flex items-center gap-2 text-blue-400">
            <Zap className="fill-blue-400" /> Lithium Calculator By Han
          </h1>
          <p className="text-slate-400 mt-1 uppercase text-xs tracking-[0.2em] font-medium">BMS LFP 15S 48V Precision Tool</p>
        </div>
        <div className="flex items-center gap-3">
          <input 
            type="file" 
            accept=".csv" 
            className="hidden" 
            ref={fileInputRef} 
            onChange={handleFileUpload} 
          />
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 transition-all px-4 py-2.5 rounded-xl font-semibold text-sm active:scale-95 group"
          >
            <FileUp className="w-4 h-4 text-emerald-400 group-hover:scale-110 transition-transform" />
            Sync BMS CSV
          </button>
          <button 
            onClick={handleReset}
            className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 transition-all px-4 py-2.5 rounded-xl font-semibold text-sm active:scale-95"
          >
            <RotateCcw className="w-4 h-4" />
            Reset
          </button>
          <button 
            onClick={fetchInsights}
            disabled={isAiLoading}
            className="flex items-center gap-2 bg-blue-600 hover:bg-blue-500 transition-all px-5 py-2.5 rounded-xl font-semibold text-sm disabled:opacity-50 shadow-lg shadow-blue-900/20 active:scale-95"
          >
            {isAiLoading ? <RefreshCw className="animate-spin w-4 h-4" /> : <Activity className="w-4 h-4" />}
            Analyze System
          </button>
        </div>
      </header>

      {uploadStatus.type !== 'idle' && (
        <div className={`flex items-center gap-3 px-4 py-3 rounded-xl border ${uploadStatus.type === 'success' ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' : 'bg-red-500/10 border-red-500/30 text-red-400'} animate-in slide-in-from-top-4 duration-300`}>
          {uploadStatus.type === 'success' ? <CheckCircle2 size={18} /> : <AlertCircle size={18} />}
          <span className="text-sm font-medium">{uploadStatus.message}</span>
          <button onClick={() => setUploadStatus({ type: 'idle', message: '' })} className="ml-auto opacity-50 hover:opacity-100">✕</button>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <div className="lg:col-span-4 space-y-6">
          <section className="bg-slate-800/50 backdrop-blur-sm rounded-2xl p-6 border border-slate-700 shadow-xl">
            <div className="flex items-center gap-2 text-blue-400 font-bold uppercase text-xs tracking-wider mb-6">
              <Settings size={16} /> Configuration
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Battery Chemistry</label>
                <select 
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 transition-all text-sm cursor-pointer"
                  value={config.chemistry}
                  onChange={(e) => handleChemistryChange(e.target.value as BatteryChemistry)}
                >
                  {Object.values(BatteryChemistry).map(c => (
                    <option key={c} value={c}>{c}</option>
                  ))}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Cell Count (S)</label>
                  <input 
                    type="number" 
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500"
                    value={config.seriesCount}
                    onChange={(e) => setConfig(prev => ({ ...prev, seriesCount: Math.max(1, parseInt(e.target.value) || 1) }))}
                  />
                </div>
                <div>
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Charge Rate (C)</label>
                    <input 
                    type="number" step="0.01" min="0.01"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono text-blue-400"
                    value={config.chargeRateC}
                    onChange={(e) => setConfig(prev => ({ ...prev, chargeRateC: parseFloat(e.target.value) || 0.01 }))}
                    />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <div className="flex justify-between items-center mb-1.5 ml-1">
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold">Total Capacity</label>
                    <UnitToggle value={capacityUnit} options={['Ah', 'mAh']} onChange={setCapacityUnit} />
                  </div>
                  <input 
                    type="number" step="0.1"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono"
                    value={capacityToDisplay(config.totalCapacityAh).toFixed(capacityUnit === 'mAh' ? 0 : 2)}
                    onChange={(e) => setConfig(prev => ({ ...prev, totalCapacityAh: displayToCapacity(parseFloat(e.target.value) || 0) }))}
                  />
                </div>
                <div>
                  <div className="flex justify-between items-center mb-1.5 ml-1">
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold">Total Energy</label>
                    <UnitToggle value={energyUnit} options={['Wh', 'kWh']} onChange={setEnergyUnit} />
                  </div>
                  <input 
                    type="number" step="0.01"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono"
                    value={energyToDisplay(totalEnergyWh).toFixed(energyUnit === 'kWh' ? 3 : 1)}
                    readOnly
                  />
                </div>
              </div>
            </div>
          </section>

          <section className="bg-slate-800/50 backdrop-blur-sm rounded-2xl p-6 border border-slate-700 shadow-xl">
            <div className="flex items-center justify-between mb-6">
              <div className="flex items-center gap-2 text-emerald-400 font-bold uppercase text-xs tracking-wider">
                <Battery size={16} /> Live Measurements
              </div>
              {uploadStatus.type === 'success' && (
                <div className="flex items-center gap-1.5 text-[8px] font-bold text-emerald-400 uppercase tracking-tighter bg-emerald-500/10 px-2 py-0.5 rounded-full border border-emerald-500/20">
                  <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                  BMS ACTIVE
                </div>
              )}
            </div>

            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Pack Voltage</label>
                  <input 
                    type="number" step="0.01"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 outline-none focus:ring-2 focus:ring-emerald-500 text-sm font-mono text-emerald-400"
                    value={state.measuredVoltage}
                    onChange={(e) => updateFromVoltage(parseFloat(e.target.value) || 0)}
                  />
                </div>
                <div>
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">BMS Voltage</label>
                  <input 
                    type="number" step="0.01"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 outline-none focus:ring-2 focus:ring-blue-500 text-sm font-mono text-blue-400"
                    value={state.bmsVoltage}
                    onChange={(e) => setState(prev => ({ ...prev, bmsVoltage: parseFloat(e.target.value) || 0 }))}
                  />
                </div>
              </div>

              <div>
                <div className="flex justify-between items-center mb-2">
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold ml-1">SOC Percentage (%)</label>
                  <div className="flex items-center gap-1">
                    <input 
                      type="number" step="0.1" min="0" max="100"
                      className="bg-slate-900 border border-slate-700 rounded px-1.5 py-0.5 text-xs font-mono font-bold text-emerald-400 w-16 text-right focus:border-emerald-500 outline-none hover:border-slate-600 transition-colors"
                      value={state.socPercentage.toFixed(1)}
                      onChange={(e) => calculateVoltageFromSOC(parseFloat(e.target.value) || 0)}
                    />
                    <span className="text-xs font-mono font-bold text-emerald-400">%</span>
                  </div>
                </div>
                <input 
                  type="range" min="0" max="100" step="0.1"
                  className="w-full h-1.5 bg-slate-900 rounded-lg appearance-none cursor-pointer accent-emerald-500"
                  value={state.socPercentage}
                  onChange={(e) => calculateVoltageFromSOC(parseFloat(e.target.value))}
                />
              </div>

              <div>
                <div className="flex justify-between items-center mb-1.5 ml-1">
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold">Remaining Capacity</label>
                  <UnitToggle value={capacityUnit} options={['Ah', 'mAh']} onChange={setCapacityUnit} />
                </div>
                <input 
                  type="number" step="0.1"
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none font-mono"
                  value={capacityToDisplay(state.remainingCapacityAh).toFixed(capacityUnit === 'mAh' ? 0 : 2)}
                  onChange={(e) => {
                    const val = parseFloat(e.target.value) || 0;
                    const ah = displayToCapacity(val);
                    const soc = (ah / config.totalCapacityAh) * 100;
                    setState(prev => ({ 
                      ...prev, 
                      remainingCapacityAh: ah, 
                      socPercentage: soc, 
                      measuredVoltage: parseFloat((getVoltageFromSOC(soc, config.chemistry) * config.seriesCount).toFixed(2)) 
                    }));
                  }}
                />
              </div>
            </div>
          </section>
        </div>

        <div className="lg:col-span-8 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700/50 shadow-lg relative overflow-hidden">
              <div className="text-slate-500 text-[10px] uppercase font-bold tracking-widest mb-1">Cell Average</div>
              <div className="text-3xl font-mono font-bold text-emerald-400">{currentCellVoltage.toFixed(3)}V</div>
              <Activity className="absolute top-4 right-4 text-slate-700 opacity-20" size={48} />
            </div>

            <div className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700/50 shadow-lg relative overflow-hidden">
              <div className="flex justify-between items-center mb-1">
                  <div className="text-slate-500 text-[10px] uppercase font-bold tracking-widest">Rem. Energy</div>
                  <UnitToggle value={energyUnit} options={['Wh', 'kWh']} onChange={setEnergyUnit} />
              </div>
              <div className="text-3xl font-mono font-bold text-blue-400">
                  {energyToDisplay((state.socPercentage / 100) * totalEnergyWh).toFixed(energyUnit === 'kWh' ? 3 : 1)}
                  <span className="text-sm ml-1 font-normal opacity-50">{energyUnit}</span>
              </div>
              <LayoutDashboard className="absolute top-4 right-4 text-slate-700 opacity-20" size={48} />
            </div>

            <div className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700/50 shadow-lg relative overflow-hidden">
              <div className="text-slate-500 text-[10px] uppercase font-bold tracking-widest mb-1">System Health</div>
              <div className="text-3xl font-mono font-bold text-amber-400">{state.socPercentage.toFixed(1)}%</div>
              <div className="w-full bg-slate-900/50 h-1.5 rounded-full mt-3 border border-slate-700/50 overflow-hidden">
                <div 
                  className={`h-full transition-all duration-500 ${state.socPercentage > 20 ? 'bg-amber-400' : 'bg-red-500 animate-pulse'}`} 
                  style={{ width: `${state.socPercentage}%` }} 
                />
              </div>
            </div>
          </div>

          <div className="space-y-6">
            <section className="bg-slate-800/50 rounded-2xl p-6 border border-slate-700 shadow-xl">
              <h2 className="text-sm font-bold uppercase tracking-widest mb-6 flex items-center gap-2 text-slate-300">
                <Activity className="text-blue-400" size={16} /> Discharge Curve Profile
              </h2>
              <div className="h-[280px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={chartData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                    <defs>
                      <linearGradient id="curveGrad" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.2}/>
                        <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
                    <XAxis dataKey="soc" hide />
                    <YAxis stroke="#475569" tick={{ fontSize: 10 }} domain={['auto', 'auto']} />
                    <Tooltip 
                      contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155', borderRadius: '12px' }}
                      itemStyle={{ color: '#60a5fa', fontSize: '12px' }}
                    />
                    <Area type="monotone" dataKey="voltage" stroke="#3b82f6" strokeWidth={2} fill="url(#curveGrad)" />
                    <ReferenceLine x={state.socPercentage} stroke="#fbbf24" strokeWidth={2} strokeDasharray="5 5" />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
              <div className="flex justify-between text-[10px] text-slate-500 font-mono mt-2 uppercase tracking-tighter">
                <span>0% SOC</span>
                <span>System Voltage (V)</span>
                <span>100% SOC</span>
              </div>
            </section>

            <section className={`bg-slate-800/50 rounded-2xl p-6 border border-slate-700 shadow-xl transition-all ${aiInsights ? 'opacity-100' : 'opacity-40 cursor-not-allowed'}`}>
              <h2 className="text-sm font-bold uppercase tracking-widest mb-4 flex items-center gap-2 text-slate-300">
                <Zap className="text-amber-400" size={16} /> Engineer Insights
              </h2>
              {aiInsights ? (
                <div className="text-xs text-slate-300 leading-relaxed whitespace-pre-line max-h-[300px] overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-slate-700">
                  {aiInsights}
                </div>
              ) : (
                <div className="flex flex-col items-center justify-center h-[200px] text-center space-y-3">
                  <Activity className="text-slate-600 animate-pulse" size={32} />
                  <p className="text-xs text-slate-500 max-w-[220px]">Analysis will generate professional LFP 15S 48V system diagnostics.</p>
                </div>
              )}
            </section>
          </div>
        </div>
      </div>

      <footer className="text-center text-slate-600 text-[10px] uppercase tracking-widest pt-8 pb-4">
        Lithium Calculator By Han &bull; LFP 15S Specialty Config &bull; 2024
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { 
  Zap, 
  Battery, 
  Activity, 
  Settings, 
  RefreshCw,
  ArrowRightLeft,
  ShieldCheck,
  RotateCcw,
  LayoutDashboard,
  FileUp,
  CheckCircle2,
  AlertCircle
} from 'lucide-react';
import { 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  AreaChart,
  Area,
  ReferenceLine
} from 'recharts';
import { BatteryChemistry, BatteryConfig, BatteryState, CapacityUnit, EnergyUnit } from './types';
import { CHEMISTRY_DEFAULTS, SOC_MAPS } from './constants';
import { getSOCFromVoltage, getVoltageFromSOC } from './utils';
import { getBatteryInsights } from './geminiService';

const INITIAL_CONFIG: BatteryConfig = {
  chemistry: BatteryChemistry.LIFEPO4,
  seriesCount: 15, 
  totalCapacityAh: 100, // Common for 48V LFP packs
  nominalCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].nominal,
  maxCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].max,
  minCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].min,
  chargeRateC: 0.5
};

const INITIAL_STATE: BatteryState = {
  measuredVoltage: 49.5, // ~3.3V per cell, high plateau for LFP
  bmsVoltage: 49.5,
  remainingCapacityAh: 80,
  socPercentage: 80,
  currentAmps: 0
};

const App: React.FC = () => {
  const [config, setConfig] = useState<BatteryConfig>(INITIAL_CONFIG);
  const [state, setState] = useState<BatteryState>(INITIAL_STATE);
  const [capacityUnit, setCapacityUnit] = useState<CapacityUnit>('Ah');
  const [energyUnit, setEnergyUnit] = useState<EnergyUnit>('kWh'); // Default to kWh for larger 48V systems
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState<boolean>(false);
  const [uploadStatus, setUploadStatus] = useState<{ type: 'success' | 'error' | 'idle', message: string }>({ type: 'idle', message: '' });

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Unit Conversion Helpers
  const capacityToDisplay = (ah: number) => capacityUnit === 'mAh' ? ah * 1000 : ah;
  const displayToCapacity = (val: number) => capacityUnit === 'mAh' ? val / 1000 : val;
  const energyToDisplay = (wh: number) => energyUnit === 'kWh' ? wh / 1000 : wh;
  const displayToEnergy = (val: number) => energyUnit === 'kWh' ? val * 1000 : val;

  // Derived Values
  const totalEnergyWh = useMemo(() => 
    config.totalCapacityAh * config.nominalCellVoltage * config.seriesCount, 
  [config.totalCapacityAh, config.nominalCellVoltage, config.seriesCount]);

  const currentCellVoltage = state.measuredVoltage / config.seriesCount;

  const handleReset = useCallback(() => {
    setConfig(INITIAL_CONFIG);
    setState(INITIAL_STATE);
    setCapacityUnit('Ah');
    setEnergyUnit('kWh');
    setAiInsights('');
    setUploadStatus({ type: 'idle', message: '' });
  }, []);

  const updateFromVoltage = useCallback((voltage: number) => {
    const cellV = voltage / config.seriesCount;
    const soc = getSOCFromVoltage(cellV, config.chemistry);
    setState(prev => ({
      ...prev,
      measuredVoltage: voltage,
      socPercentage: soc,
      remainingCapacityAh: (soc / 100) * config.totalCapacityAh
    }));
  }, [config.seriesCount, config.chemistry, config.totalCapacityAh]);

  const calculateVoltageFromSOC = useCallback((soc: number) => {
    const safeSoc = Math.min(100, Math.max(0, soc));
    const cellV = getVoltageFromSOC(safeSoc, config.chemistry);
    setState(prev => ({ 
      ...prev, 
      socPercentage: safeSoc,
      measuredVoltage: parseFloat((cellV * config.seriesCount).toFixed(2)),
      remainingCapacityAh: (safeSoc / 100) * config.totalCapacityAh
    }));
  }, [config.chemistry, config.seriesCount, config.totalCapacityAh]);

  const handleChemistryChange = (chem: BatteryChemistry) => {
    const defaults = CHEMISTRY_DEFAULTS[chem];
    setConfig(prev => ({
      ...prev,
      chemistry: chem,
      nominalCellVoltage: defaults.nominal,
      maxCellVoltage: defaults.max,
      minCellVoltage: defaults.min
    }));
  };

  const fetchInsights = useCallback(async () => {
    setIsAiLoading(true);
    const insights = await getBatteryInsights(
      config.chemistry,
      state.measuredVoltage,
      state.socPercentage,
      config.seriesCount,
      state.bmsVoltage,
      config.totalCapacityAh,
      config.chargeRateC
    );
    setAiInsights(insights || 'No insights available.');
    setIsAiLoading(false);
  }, [config, state]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (!text) return;

      try {
        const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
        if (lines.length < 2) throw new Error("File contains no data rows.");

        // Intelligent Delimiter Detection
        const firstLine = lines[0];
        const delimiters = [',', ';', '\t'];
        const delimiterCounts = delimiters.map(d => (firstLine.match(new RegExp(d, 'g')) || []).length);
        const maxDelimiterIdx = delimiterCounts.indexOf(Math.max(...delimiterCounts));
        const delimiter = delimiterCounts[maxDelimiterIdx] > 0 ? delimiters[maxDelimiterIdx] : ',';

        const headers = lines[0].toLowerCase().split(delimiter).map(h => h.trim());

        // Find the latest valid data row (working backwards from the end of the file)
        let dataRow: string[] = [];
        for (let i = lines.length - 1; i >= 1; i--) {
          const row = lines[i].split(delimiter).map(d => d.trim());
          // A row is considered valid if it has content and at least some numeric values
          if (row.length >= headers.length && row.some(cell => !isNaN(parseFloat(cell)))) {
            dataRow = row;
            break;
          }
        }

        if (dataRow.length === 0) throw new Error("No valid data rows found in the CSV.");

        const getVal = (keywords: string[]) => {
          const index = headers.findIndex(h => keywords.some(k => h.includes(k)));
          if (index === -1) return null;
          const val = parseFloat(dataRow[index]);
          return isNaN(val) ? null : val;
        };

        // Expanded keyword mapping
        const importedVoltage = getVal(['volt', 'v_pack', 'pack_v', 'total_v', 'battery_v', 'voltage']);
        const importedSoc = getVal(['soc', 'percent', 'cap_%', 'capacity_%', 'charge_%', 'state_of_charge']);
        const importedCurrent = getVal(['curr', 'amp', 'i_pack', 'current', 'pack_i', 'discharge_a', 'charge_a']);
        const importedCapacity = getVal(['rem', 'capacity_ah', 'ah_rem', 'left_ah', 'remaining_cap', 'capacity_remaining']);
        const importedBmsV = getVal(['bms_v', 'internal_v', 'cell_sum', 'bms_voltage']);

        if (importedVoltage === null && importedSoc === null) {
          throw new Error("Missing essential columns: Could not find Pack Voltage or SOC.");
        }

        setState(prev => {
          const newState = { ...prev };

          if (importedVoltage !== null) {
            newState.measuredVoltage = importedVoltage;
          }

          if (importedBmsV !== null) {
            newState.bmsVoltage = importedBmsV;
          } else if (importedVoltage !== null) {
            newState.bmsVoltage = importedVoltage; // Fallback to pack voltage if BMS-specific internal V isn't provided
          }

          if (importedCurrent !== null) {
            newState.currentAmps = importedCurrent;
          }

          // Logic for synchronizing SOC and Voltage
          if (importedSoc !== null) {
            // Clamp SOC to valid range
            newState.socPercentage = Math.min(100, Math.max(0, importedSoc));
            newState.remainingCapacityAh = (newState.socPercentage / 100) * config.totalCapacityAh;
          } else if (importedVoltage !== null) {
            // Calculate SOC from Voltage if SOC column is missing
            const soc = getSOCFromVoltage(importedVoltage / config.seriesCount, config.chemistry);
            newState.socPercentage = soc;
            newState.remainingCapacityAh = (soc / 100) * config.totalCapacityAh;
          }

          if (importedCapacity !== null) {
            newState.remainingCapacityAh = importedCapacity;
            // Recalculate SOC based on actual remaining capacity if provided
            newState.socPercentage = Math.min(100, (importedCapacity / config.totalCapacityAh) * 100);
          }

          return newState;
        });

        setUploadStatus({ 
          type: 'success', 
          message: `Successfully synchronized BMS data (${file.name}). Found ${headers.length} columns.` 
        });
      } catch (err) {
        setUploadStatus({ 
          type: 'error', 
          message: `${err instanceof Error ? err.message : 'Invalid CSV format or parsing error.'}` 
        });
      }
    };
    reader.onerror = () => setUploadStatus({ type: 'error', message: 'Failed to read the file.' });
    reader.readAsText(file);
    event.target.value = '';
  };

  const chartData = useMemo(() => {
    return SOC_MAPS[config.chemistry].map(point => ({
      soc: point.soc,
      voltage: parseFloat((point.v * config.seriesCount).toFixed(2)),
      cellVoltage: parseFloat(point.v.toFixed(3))
    })).sort((a, b) => a.soc - b.soc);
  }, [config.chemistry, config.seriesCount]);

  const UnitToggle = ({ value, options, onChange }: { value: string, options: string[], onChange: (v: any) => void }) => (
    <div className="flex bg-slate-900 rounded-lg p-0.5 border border-slate-700 h-6">
      {options.map(opt => (
        <button
          key={opt}
          onClick={() => onChange(opt)}
          className={`px-2 text-[8px] font-bold uppercase tracking-widest rounded transition-all ${value === opt ? 'bg-blue-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}
        >
          {opt}
        </button>
      ))}
    </div>
  );

  return (
    <div className="min-h-screen p-4 md:p-8 max-w-7xl mx-auto space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-slate-700 pb-6">
        <div>
          <h1 className="text-3xl font-bold flex items-center gap-2 text-blue-400">
            <Zap className="fill-blue-400" /> Lithium Calculator By Han
          </h1>
          <p className="text-slate-400 mt-1 uppercase text-xs tracking-[0.2em] font-medium">BMS LFP 15S 48V Precision Tool</p>
        </div>
        <div className="flex items-center gap-3">
          <input 
            type="file" 
            accept=".csv" 
            className="hidden" 
            ref={fileInputRef} 
            onChange={handleFileUpload} 
          />
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 transition-all px-4 py-2.5 rounded-xl font-semibold text-sm active:scale-95 group"
          >
            <FileUp className="w-4 h-4 text-emerald-400 group-hover:scale-110 transition-transform" />
            Sync BMS CSV
          </button>
          <button 
            onClick={handleReset}
            className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 transition-all px-4 py-2.5 rounded-xl font-semibold text-sm active:scale-95"
          >
            <RotateCcw className="w-4 h-4" />
            Reset
          </button>
          <button 
            onClick={fetchInsights}
            disabled={isAiLoading}
            className="flex items-center gap-2 bg-blue-600 hover:bg-blue-500 transition-all px-5 py-2.5 rounded-xl font-semibold text-sm disabled:opacity-50 shadow-lg shadow-blue-900/20 active:scale-95"
          >
            {isAiLoading ? <RefreshCw className="animate-spin w-4 h-4" /> : <Activity className="w-4 h-4" />}
            Analyze System
          </button>
        </div>
      </header>

      {uploadStatus.type !== 'idle' && (
        <div className={`flex items-center gap-3 px-4 py-3 rounded-xl border ${uploadStatus.type === 'success' ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' : 'bg-red-500/10 border-red-500/30 text-red-400'} animate-in slide-in-from-top-4 duration-300`}>
          {uploadStatus.type === 'success' ? <CheckCircle2 size={18} /> : <AlertCircle size={18} />}
          <span className="text-sm font-medium">{uploadStatus.message}</span>
          <button onClick={() => setUploadStatus({ type: 'idle', message: '' })} className="ml-auto opacity-50 hover:opacity-100">✕</button>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <div className="lg:col-span-4 space-y-6">
          <section className="bg-slate-800/50 backdrop-blur-sm rounded-2xl p-6 border border-slate-700 shadow-xl">
            <div className="flex items-center gap-2 text-blue-400 font-bold uppercase text-xs tracking-wider mb-6">
              <Settings size={16} /> Configuration
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Battery Chemistry</label>
                <select 
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 transition-all text-sm cursor-pointer"
                  value={config.chemistry}
                  onChange={(e) => handleChemistryChange(e.target.value as BatteryChemistry)}
                >
                  {Object.values(BatteryChemistry).map(c => (
                    <option key={c} value={c}>{c}</option>
                  ))}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Cell Count (S)</label>
                  <input 
                    type="number" 
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500"
                    value={config.seriesCount}
                    onChange={(e) => setConfig(prev => ({ ...prev, seriesCount: Math.max(1, parseInt(e.target.value) || 1) }))}
                  />
                </div>
                <div>
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Charge Rate (C)</label>
                    <input 
                    type="number" step="0.01" min="0.01"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono text-blue-400"
                    value={config.chargeRateC}
                    onChange={(e) => setConfig(prev => ({ ...prev, chargeRateC: parseFloat(e.target.value) || 0.01 }))}
                    />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <div className="flex justify-between items-center mb-1.5 ml-1">
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold">Total Capacity</label>
                    <UnitToggle value={capacityUnit} options={['Ah', 'mAh']} onChange={setCapacityUnit} />
                  </div>
                  <input 
                    type="number" step="0.1"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono"
                    value={capacityToDisplay(config.totalCapacityAh).toFixed(capacityUnit === 'mAh' ? 0 : 2)}
                    onChange={(e) => setConfig(prev => ({ ...prev, totalCapacityAh: displayToCapacity(parseFloat(e.target.value) || 0) }))}
                  />
                </div>
                <div>
                  <div className="flex justify-between items-center mb-1.5 ml-1">
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold">Total Energy</label>
                    <UnitToggle value={energyUnit} options={['Wh', 'kWh']} onChange={setEnergyUnit} />
                  </div>
                  <input 
                    type="number" step="0.01"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono"
                    value={energyToDisplay(totalEnergyWh).toFixed(energyUnit === 'kWh' ? 3 : 1)}
                    readOnly
                  />
                </div>
              </div>
            </div>
          </section>

          <section className="bg-slate-800/50 backdrop-blur-sm rounded-2xl p-6 border border-slate-700 shadow-xl">
            <div className="flex items-center justify-between mb-6">
              <div className="flex items-center gap-2 text-emerald-400 font-bold uppercase text-xs tracking-wider">
                <Battery size={16} /> Live Measurements
              </div>
              {uploadStatus.type === 'success' && (
                <div className="flex items-center gap-1.5 text-[8px] font-bold text-emerald-400 uppercase tracking-tighter bg-emerald-500/10 px-2 py-0.5 rounded-full border border-emerald-500/20">
                  <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                  BMS ACTIVE
                </div>
              )}
            </div>

            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Pack Voltage</label>
                  <input 
                    type="number" step="0.01"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 outline-none focus:ring-2 focus:ring-emerald-500 text-sm font-mono text-emerald-400"
                    value={state.measuredVoltage}
                    onChange={(e) => updateFromVoltage(parseFloat(e.target.value) || 0)}
                  />
                </div>
                <div>
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">BMS Voltage</label>
                  <input 
                    type="number" step="0.01"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 outline-none focus:ring-2 focus:ring-blue-500 text-sm font-mono text-blue-400"
                    value={state.bmsVoltage}
                    onChange={(e) => setState(prev => ({ ...prev, bmsVoltage: parseFloat(e.target.value) || 0 }))}
                  />
                </div>
              </div>

              <div>
                <div className="flex justify-between items-center mb-2">
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold ml-1">SOC Percentage (%)</label>
                  <div className="flex items-center gap-1">
                    <input 
                      type="number" step="0.1" min="0" max="100"
                      className="bg-slate-900 border border-slate-700 rounded px-1.5 py-0.5 text-xs font-mono font-bold text-emerald-400 w-16 text-right focus:border-emerald-500 outline-none hover:border-slate-600 transition-colors"
                      value={state.socPercentage.toFixed(1)}
                      onChange={(e) => calculateVoltageFromSOC(parseFloat(e.target.value) || 0)}
                    />
                    <span className="text-xs font-mono font-bold text-emerald-400">%</span>
                  </div>
                </div>
                <input 
                  type="range" min="0" max="100" step="0.1"
                  className="w-full h-1.5 bg-slate-900 rounded-lg appearance-none cursor-pointer accent-emerald-500"
                  value={state.socPercentage}
                  onChange={(e) => calculateVoltageFromSOC(parseFloat(e.target.value))}
                />
              </div>

              <div>
                <div className="flex justify-between items-center mb-1.5 ml-1">
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold">Remaining Capacity</label>
                  <UnitToggle value={capacityUnit} options={['Ah', 'mAh']} onChange={setCapacityUnit} />
                </div>
                <input 
                  type="number" step="0.1"
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none font-mono"
                  value={capacityToDisplay(state.remainingCapacityAh).toFixed(capacityUnit === 'mAh' ? 0 : 2)}
                  onChange={(e) => {
                    const val = parseFloat(e.target.value) || 0;
                    const ah = displayToCapacity(val);
                    const soc = (ah / config.totalCapacityAh) * 100;
                    setState(prev => ({ 
                      ...prev, 
                      remainingCapacityAh: ah, 
                      socPercentage: soc, 
                      measuredVoltage: parseFloat((getVoltageFromSOC(soc, config.chemistry) * config.seriesCount).toFixed(2)) 
                    }));
                  }}
                />
              </div>
            </div>
          </section>
        </div>

        <div className="lg:col-span-8 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700/50 shadow-lg relative overflow-hidden">
              <div className="text-slate-500 text-[10px] uppercase font-bold tracking-widest mb-1">Cell Average</div>
              <div className="text-3xl font-mono font-bold text-emerald-400">{currentCellVoltage.toFixed(3)}V</div>
              <Activity className="absolute top-4 right-4 text-slate-700 opacity-20" size={48} />
            </div>

            <div className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700/50 shadow-lg relative overflow-hidden">
              <div className="flex justify-between items-center mb-1">
                  <div className="text-slate-500 text-[10px] uppercase font-bold tracking-widest">Rem. Energy</div>
                  <UnitToggle value={energyUnit} options={['Wh', 'kWh']} onChange={setEnergyUnit} />
              </div>
              <div className="text-3xl font-mono font-bold text-blue-400">
                  {energyToDisplay((state.socPercentage / 100) * totalEnergyWh).toFixed(energyUnit === 'kWh' ? 3 : 1)}
                  <span className="text-sm ml-1 font-normal opacity-50">{energyUnit}</span>
              </div>
              <LayoutDashboard className="absolute top-4 right-4 text-slate-700 opacity-20" size={48} />
            </div>

            <div className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700/50 shadow-lg relative overflow-hidden">
              <div className="text-slate-500 text-[10px] uppercase font-bold tracking-widest mb-1">System Health</div>
              <div className="text-3xl font-mono font-bold text-amber-400">{state.socPercentage.toFixed(1)}%</div>
              <div className="w-full bg-slate-900/50 h-1.5 rounded-full mt-3 border border-slate-700/50 overflow-hidden">
                <div 
                  className={`h-full transition-all duration-500 ${state.socPercentage > 20 ? 'bg-amber-400' : 'bg-red-500 animate-pulse'}`} 
                  style={{ width: `${state.socPercentage}%` }} 
                />
              </div>
            </div>
          </div>

          <div className="space-y-6">
            <section className="bg-slate-800/50 rounded-2xl p-6 border border-slate-700 shadow-xl">
              <h2 className="text-sm font-bold uppercase tracking-widest mb-6 flex items-center gap-2 text-slate-300">
                <Activity className="text-blue-400" size={16} /> Discharge Curve Profile
              </h2>
              <div className="h-[280px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={chartData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                    <defs>
                      <linearGradient id="curveGrad" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.2}/>
                        <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
                    <XAxis dataKey="soc" hide />
                    <YAxis stroke="#475569" tick={{ fontSize: 10 }} domain={['auto', 'auto']} />
                    <Tooltip 
                      contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155', borderRadius: '12px' }}
                      itemStyle={{ color: '#60a5fa', fontSize: '12px' }}
                    />
                    <Area type="monotone" dataKey="voltage" stroke="#3b82f6" strokeWidth={2} fill="url(#curveGrad)" />
                    <ReferenceLine x={state.socPercentage} stroke="#fbbf24" strokeWidth={2} strokeDasharray="5 5" />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
              <div className="flex justify-between text-[10px] text-slate-500 font-mono mt-2 uppercase tracking-tighter">
                <span>0% SOC</span>
                <span>System Voltage (V)</span>
                <span>100% SOC</span>
              </div>
            </section>

            <section className={`bg-slate-800/50 rounded-2xl p-6 border border-slate-700 shadow-xl transition-all ${aiInsights ? 'opacity-100' : 'opacity-40 cursor-not-allowed'}`}>
              <h2 className="text-sm font-bold uppercase tracking-widest mb-4 flex items-center gap-2 text-slate-300">
                <Zap className="text-amber-400" size={16} /> Engineer Insights
              </h2>
              {aiInsights ? (
                <div className="text-xs text-slate-300 leading-relaxed whitespace-pre-line max-h-[300px] overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-slate-700">
                  {aiInsights}
                </div>
              ) : (
                <div className="flex flex-col items-center justify-center h-[200px] text-center space-y-3">
                  <Activity className="text-slate-600 animate-pulse" size={32} />
                  <p className="text-xs text-slate-500 max-w-[220px]">Analysis will generate professional LFP 15S 48V system diagnostics.</p>
                </div>
              )}
            </section>
          </div>
        </div>
      </div>

      <footer className="text-center text-slate-600 text-[10px] uppercase tracking-widest pt-8 pb-4">
        Lithium Calculator By Han &bull; LFP 15S Specialty Config &bull; 2024
      </footer>
    </div>
  );
};

export default App;

export enum BatteryChemistry {
  LI_ION = 'Li-ion (NMC/NCA)',
  LIFEPO4 = 'LiFePO4 (LFP)',
  LIPO = 'Li-Polymer'
}

export type CapacityUnit = 'Ah' | 'mAh';
export type EnergyUnit = 'Wh' | 'kWh';

export interface BatteryConfig {
  chemistry: BatteryChemistry;
  seriesCount: number;
  totalCapacityAh: number;
  nominalCellVoltage: number;
  maxCellVoltage: number;
  minCellVoltage: number;
  chargeRateC: number; 
}

export interface BatteryState {
  measuredVoltage: number;
  bmsVoltage: number;
  remainingCapacityAh: number;
  socPercentage: number;
  currentAmps: number;
  temperatureCelsius?: number;
}

export interface HistoryPoint extends BatteryState {
  timestamp: number;
  id: string;
}

export interface CalculationResult {
  estimatedSOC: number;
  totalEnergyWh: number;
  remainingEnergyWh: number;
  voltagePerCell: number;
  estimatedRemainingAh: number;
}

import React, { useState, useMemo, useCallback, useRef } from 'react';
import { 
  Zap, 
  Battery, 
  Activity, 
  Settings, 
  RefreshCw,
  RotateCcw,
  LayoutDashboard,
  FileUp,
  CheckCircle2,
  AlertCircle,
  History as HistoryIcon,
  Trash2,
  Thermometer,
  Clock,
  TrendingUp,
  Download
} from 'lucide-react';
import { 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  AreaChart,
  Area,
  ReferenceLine,
  LineChart,
  Line,
  Legend
} from 'recharts';
import { BatteryChemistry, BatteryConfig, BatteryState, CapacityUnit, EnergyUnit, HistoryPoint } from './types';
import { CHEMISTRY_DEFAULTS, SOC_MAPS } from './constants';
import { getSOCFromVoltage, getVoltageFromSOC } from './utils';
import { getBatteryInsights } from './geminiService';

const INITIAL_CONFIG: BatteryConfig = {
  chemistry: BatteryChemistry.LIFEPO4,
  seriesCount: 15, 
  totalCapacityAh: 100,
  nominalCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].nominal,
  maxCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].max,
  minCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].min,
  chargeRateC: 0.5
};

const INITIAL_STATE: BatteryState = {
  measuredVoltage: 49.5,
  bmsVoltage: 49.5,
  remainingCapacityAh: 80,
  socPercentage: 80,
  currentAmps: 0,
  temperatureCelsius: 25
};

const App: React.FC = () => {
  const [config, setConfig] = useState<BatteryConfig>(INITIAL_CONFIG);
  const [state, setState] = useState<BatteryState>(INITIAL_STATE);
  const [history, setHistory] = useState<HistoryPoint[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'history'>('dashboard');
  const [capacityUnit, setCapacityUnit] = useState<CapacityUnit>('Ah');
  const [energyUnit, setEnergyUnit] = useState<EnergyUnit>('kWh');
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState<boolean>(false);
  const [uploadStatus, setUploadStatus] = useState<{ type: 'success' | 'error' | 'idle', message: string }>({ type: 'idle', message: '' });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const capacityToDisplay = (ah: number) => capacityUnit === 'mAh' ? ah * 1000 : ah;
  const displayToCapacity = (val: number) => capacityUnit === 'mAh' ? val / 1000 : val;
  const energyToDisplay = (wh: number) => energyUnit === 'kWh' ? wh / 1000 : wh;

  const totalEnergyWh = useMemo(() => 
    config.totalCapacityAh * config.nominalCellVoltage * config.seriesCount, 
  [config.totalCapacityAh, config.nominalCellVoltage, config.seriesCount]);

  const currentCellVoltage = state.measuredVoltage / config.seriesCount;

  const logCurrentState = useCallback((overrides?: Partial<BatteryState>) => {
    const entry: HistoryPoint = {
      ...state,
      ...overrides,
      timestamp: Date.now(),
      id: crypto.randomUUID()
    };
    setHistory(prev => [entry, ...prev].slice(0, 100)); // Keep last 100 entries
  }, [state]);

  const handleReset = useCallback(() => {
    setConfig(INITIAL_CONFIG);
    setState(INITIAL_STATE);
    setHistory([]);
    setAiInsights('');
    setUploadStatus({ type: 'idle', message: '' });
    setActiveTab('dashboard');
  }, []);

  const updateFromVoltage = useCallback((voltage: number) => {
    const cellV = voltage / config.seriesCount;
    const soc = getSOCFromVoltage(cellV, config.chemistry);
    setState(prev => ({
      ...prev,
      measuredVoltage: voltage,
      socPercentage: soc,
      remainingCapacityAh: (soc / 100) * config.totalCapacityAh
    }));
  }, [config.seriesCount, config.chemistry, config.totalCapacityAh]);

  const calculateVoltageFromSOC = useCallback((soc: number) => {
    const safeSoc = Math.min(100, Math.max(0, soc));
    const cellV = getVoltageFromSOC(safeSoc, config.chemistry);
    setState(prev => ({ 
      ...prev, 
      socPercentage: safeSoc,
      measuredVoltage: parseFloat((cellV * config.seriesCount).toFixed(2)),
      remainingCapacityAh: (safeSoc / 100) * config.totalCapacityAh
    }));
  }, [config.chemistry, config.seriesCount, config.totalCapacityAh]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (!text) return;

      try {
        const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
        if (lines.length < 2) throw new Error("File contains no data rows.");

        const firstLine = lines[0];
        const delimiters = [',', ';', '\t'];
        const delimiterCounts = delimiters.map(d => (firstLine.match(new RegExp(d, 'g')) || []).length);
        const maxDelimiterIdx = delimiterCounts.indexOf(Math.max(...delimiterCounts));
        const delimiter = delimiterCounts[maxDelimiterIdx] > 0 ? delimiters[maxDelimiterIdx] : ',';

        const headers = lines[0].toLowerCase().split(delimiter).map(h => h.trim());
        let dataRow: string[] = [];
        for (let i = lines.length - 1; i >= 1; i--) {
          const row = lines[i].split(delimiter).map(d => d.trim());
          if (row.length >= headers.length && row.some(cell => !isNaN(parseFloat(cell)))) {
            dataRow = row;
            break;
          }
        }

        if (dataRow.length === 0) throw new Error("No valid data rows found in the CSV.");

        const getVal = (keywords: string[]) => {
          const index = headers.findIndex(h => keywords.some(k => h.includes(k)));
          if (index === -1) return null;
          const val = parseFloat(dataRow[index]);
          return isNaN(val) ? null : val;
        };

        const importedVoltage = getVal(['volt', 'v_pack', 'pack_v', 'total_v', 'battery_v', 'voltage']);
        const importedSoc = getVal(['soc', 'percent', 'cap_%', 'capacity_%', 'charge_%', 'state_of_charge']);
        const importedCurrent = getVal(['curr', 'amp', 'i_pack', 'current', 'pack_i', 'discharge_a', 'charge_a']);
        const importedCapacity = getVal(['rem', 'capacity_ah', 'ah_rem', 'left_ah', 'remaining_cap', 'capacity_remaining']);
        const importedBmsV = getVal(['bms_v', 'internal_v', 'cell_sum', 'bms_voltage']);
        const importedTemp = getVal(['temp', 'cel', 't_pack', 't_ambient', 'temperature']);

        if (importedVoltage === null && importedSoc === null) {
          throw new Error("Missing essential columns: Could not find Pack Voltage or SOC.");
        }

        const nextState: BatteryState = {
          ...state,
          measuredVoltage: importedVoltage ?? state.measuredVoltage,
          bmsVoltage: importedBmsV ?? importedVoltage ?? state.bmsVoltage,
          currentAmps: importedCurrent ?? state.currentAmps,
          temperatureCelsius: importedTemp ?? state.temperatureCelsius
        };

        if (importedSoc !== null) {
          nextState.socPercentage = Math.min(100, Math.max(0, importedSoc));
          nextState.remainingCapacityAh = (nextState.socPercentage / 100) * config.totalCapacityAh;
        } else if (importedVoltage !== null) {
          const soc = getSOCFromVoltage(importedVoltage / config.seriesCount, config.chemistry);
          nextState.socPercentage = soc;
          nextState.remainingCapacityAh = (soc / 100) * config.totalCapacityAh;
        }

        if (importedCapacity !== null) {
          nextState.remainingCapacityAh = importedCapacity;
          nextState.socPercentage = Math.min(100, (importedCapacity / config.totalCapacityAh) * 100);
        }

        setState(nextState);
        logCurrentState(nextState); // Auto-log on sync
        setUploadStatus({ 
          type: 'success', 
          message: `Successfully synchronized and logged data from ${file.name}.` 
        });
      } catch (err) {
        setUploadStatus({ 
          type: 'error', 
          message: `${err instanceof Error ? err.message : 'Invalid CSV format.'}` 
        });
      }
    };
    reader.readAsText(file);
    event.target.value = '';
  };

  const chartData = useMemo(() => {
    return SOC_MAPS[config.chemistry].map(point => ({
      soc: point.soc,
      voltage: parseFloat((point.v * config.seriesCount).toFixed(2)),
      cellVoltage: parseFloat(point.v.toFixed(3))
    })).sort((a, b) => a.soc - b.soc);
  }, [config.chemistry, config.seriesCount]);

  const historyTrendData = useMemo(() => {
    return [...history].reverse().map(h => ({
      time: new Date(h.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
      voltage: h.measuredVoltage,
      soc: h.socPercentage,
      temp: h.temperatureCelsius
    }));
  }, [history]);

  const UnitToggle = ({ value, options, onChange }: { value: string, options: string[], onChange: (v: any) => void }) => (
    <div className="flex bg-slate-900 rounded-lg p-0.5 border border-slate-700 h-6">
      {options.map(opt => (
        <button
          key={opt}
          onClick={() => onChange(opt)}
          className={`px-2 text-[8px] font-bold uppercase tracking-widest rounded transition-all ${value === opt ? 'bg-blue-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}
        >
          {opt}
        </button>
      ))}
    </div>
  );

  return (
    <div className="min-h-screen p-4 md:p-8 max-w-7xl mx-auto space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-slate-700 pb-6">
        <div>
          <h1 className="text-3xl font-bold flex items-center gap-2 text-blue-400">
            <Zap className="fill-blue-400" /> Lithium Calculator By Han
          </h1>
          <div className="flex items-center gap-4 mt-2">
            <button 
              onClick={() => setActiveTab('dashboard')}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-widest transition-all ${activeTab === 'dashboard' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-800 text-slate-400 hover:text-slate-200'}`}
            >
              <LayoutDashboard size={14} /> Dashboard
            </button>
            <button 
              onClick={() => setActiveTab('history')}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-widest transition-all ${activeTab === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-800 text-slate-400 hover:text-slate-200'}`}
            >
              <HistoryIcon size={14} /> History Log {history.length > 0 && <span className="ml-1 opacity-60">({history.length})</span>}
            </button>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <input 
            type="file" 
            accept=".csv" 
            className="hidden" 
            ref={fileInputRef} 
            onChange={handleFileUpload} 
          />
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 transition-all px-4 py-2.5 rounded-xl font-semibold text-sm active:scale-95 group"
          >
            <FileUp className="w-4 h-4 text-emerald-400 group-hover:scale-110 transition-transform" />
            Sync BMS CSV
          </button>
          <button 
            onClick={handleReset}
            className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 transition-all px-4 py-2.5 rounded-xl font-semibold text-sm active:scale-95 text-red-400"
          >
            <RotateCcw className="w-4 h-4" />
            Reset
          </button>
        </div>
      </header>

      {uploadStatus.type !== 'idle' && (
        <div className={`flex items-center gap-3 px-4 py-3 rounded-xl border ${uploadStatus.type === 'success' ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' : 'bg-red-500/10 border-red-500/30 text-red-400'} animate-in slide-in-from-top-4 duration-300`}>
          {uploadStatus.type === 'success' ? <CheckCircle2 size={18} /> : <AlertCircle size={18} />}
          <span className="text-sm font-medium">{uploadStatus.message}</span>
          <button onClick={() => setUploadStatus({ type: 'idle', message: '' })} className="ml-auto opacity-50 hover:opacity-100">✕</button>
        </div>
      )}

      {activeTab === 'dashboard' ? (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 animate-in fade-in duration-500">
          <div className="lg:col-span-4 space-y-6">
            {/* Configuration Section */}
            <section className="bg-slate-800/50 backdrop-blur-sm rounded-2xl p-6 border border-slate-700 shadow-xl">
              <div className="flex items-center gap-2 text-blue-400 font-bold uppercase text-xs tracking-wider mb-6">
                <Settings size={16} /> Configuration
              </div>
              <div className="space-y-4">
                <div>
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Battery Chemistry</label>
                  <select 
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 transition-all text-sm cursor-pointer"
                    value={config.chemistry}
                    onChange={(e) => setConfig(prev => ({ ...prev, chemistry: e.target.value as BatteryChemistry }))}
                  >
                    {Object.values(BatteryChemistry).map(c => (
                      <option key={c} value={c}>{c}</option>
                    ))}
                  </select>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Cell Count (S)</label>
                    <input 
                      type="number" 
                      className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500"
                      value={config.seriesCount}
                      onChange={(e) => setConfig(prev => ({ ...prev, seriesCount: Math.max(1, parseInt(e.target.value) || 1) }))}
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Charge Rate (C)</label>
                    <input 
                      type="number" step="0.01" 
                      className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono text-blue-400"
                      value={config.chargeRateC}
                      onChange={(e) => setConfig(prev => ({ ...prev, chargeRateC: parseFloat(e.target.value) || 0.01 }))}
                    />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <div className="flex justify-between items-center mb-1.5 ml-1">
                      <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold">Total Capacity</label>
                      <UnitToggle value={capacityUnit} options={['Ah', 'mAh']} onChange={setCapacityUnit} />
                    </div>
                    <input 
                      type="number" step="0.1"
                      className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono"
                      value={capacityToDisplay(config.totalCapacityAh).toFixed(capacityUnit === 'mAh' ? 0 : 2)}
                      onChange={(e) => setConfig(prev => ({ ...prev, totalCapacityAh: displayToCapacity(parseFloat(e.target.value) || 0) }))}
                    />
                  </div>
                  <div>
                    <div className="flex justify-between items-center mb-1.5 ml-1">
                      <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold">Total Energy</label>
                      <UnitToggle value={energyUnit} options={['Wh', 'kWh']} onChange={setEnergyUnit} />
                    </div>
                    <input 
                      type="number" step="0.01"
                      className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono"
                      value={energyToDisplay(totalEnergyWh).toFixed(energyUnit === 'kWh' ? 3 : 1)}
                      readOnly
                    />
                  </div>
                </div>
              </div>
            </section>

            {/* Live Measurements Section */}
            <section className="bg-slate-800/50 backdrop-blur-sm rounded-2xl p-6 border border-slate-700 shadow-xl">
              <div className="flex items-center justify-between mb-6">
                <div className="flex items-center gap-2 text-emerald-400 font-bold uppercase text-xs tracking-wider">
                  <Battery size={16} /> Live Measurements
                </div>
                <button 
                  onClick={() => {
                    logCurrentState();
                    setUploadStatus({ type: 'success', message: 'Manual snapshot captured.' });
                  }}
                  className="text-[10px] font-bold text-slate-400 hover:text-white uppercase flex items-center gap-1.5 bg-slate-900 px-3 py-1 rounded-lg border border-slate-700 transition-all hover:bg-slate-700"
                >
                  <TrendingUp size={12} /> Log Snapshot
                </button>
              </div>

              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Pack Voltage</label>
                    <input 
                      type="number" step="0.01"
                      className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 outline-none focus:ring-2 focus:ring-emerald-500 text-sm font-mono text-emerald-400"
                      value={state.measuredVoltage}
                      onChange={(e) => updateFromVoltage(parseFloat(e.target.value) || 0)}
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Temperature (°C)</label>
                    <div className="relative">
                      <input 
                        type="number" step="0.1"
                        className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 outline-none focus:ring-2 focus:ring-amber-500 text-sm font-mono text-amber-400 pr-8"
                        value={state.temperatureCelsius}
                        onChange={(e) => setState(prev => ({ ...prev, temperatureCelsius: parseFloat(e.target.value) || 0 }))}
                      />
                      <Thermometer className="absolute right-3 top-2.5 text-slate-600" size={14} />
                    </div>
                  </div>
                </div>

                <div>
                  <div className="flex justify-between items-center mb-2">
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold ml-1">SOC Percentage (%)</label>
                    <input 
                      type="number" step="0.1" min="0" max="100"
                      className="bg-slate-900 border border-slate-700 rounded px-1.5 py-0.5 text-xs font-mono font-bold text-emerald-400 w-16 text-right focus:border-emerald-500 outline-none"
                      value={state.socPercentage.toFixed(1)}
                      onChange={(e) => calculateVoltageFromSOC(parseFloat(e.target.value) || 0)}
                    />
                  </div>
                  <input 
                    type="range" min="0" max="100" step="0.1"
                    className="w-full h-1.5 bg-slate-900 rounded-lg appearance-none cursor-pointer accent-emerald-500"
                    value={state.socPercentage}
                    onChange={(e) => calculateVoltageFromSOC(parseFloat(e.target.value))}
                  />
                </div>

                <div>
                  <div className="flex justify-between items-center mb-1.5 ml-1">
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold">Remaining Capacity</label>
                    <UnitToggle value={capacityUnit} options={['Ah', 'mAh']} onChange={setCapacityUnit} />
                  </div>
                  <input 
                    type="number" step="0.1"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none font-mono"
                    value={capacityToDisplay(state.remainingCapacityAh).toFixed(capacityUnit === 'mAh' ? 0 : 2)}
                    onChange={(e) => {
                      const ah = displayToCapacity(parseFloat(e.target.value) || 0);
                      const soc = (ah / config.totalCapacityAh) * 100;
                      setState(prev => ({ 
                        ...prev, 
                        remainingCapacityAh: ah, 
                        socPercentage: soc, 
                        measuredVoltage: parseFloat((getVoltageFromSOC(soc, config.chemistry) * config.seriesCount).toFixed(2)) 
                      }));
                    }}
                  />
                </div>
              </div>
            </section>
          </div>

          <div className="lg:col-span-8 space-y-6">
            {/* Quick Stats Grid */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700/50 shadow-lg relative overflow-hidden">
                <div className="text-slate-500 text-[10px] uppercase font-bold tracking-widest mb-1">Cell Average</div>
                <div className="text-3xl font-mono font-bold text-emerald-400">{currentCellVoltage.toFixed(3)}V</div>
                <Activity className="absolute top-4 right-4 text-slate-700 opacity-20" size={48} />
              </div>
              <div className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700/50 shadow-lg relative overflow-hidden">
                <div className="flex justify-between items-center mb-1">
                    <div className="text-slate-500 text-[10px] uppercase font-bold tracking-widest">Rem. Energy</div>
                </div>
                <div className="text-3xl font-mono font-bold text-blue-400">
                    {energyToDisplay((state.socPercentage / 100) * totalEnergyWh).toFixed(energyUnit === 'kWh' ? 3 : 1)}
                    <span className="text-sm ml-1 font-normal opacity-50">{energyUnit}</span>
                </div>
                <LayoutDashboard className="absolute top-4 right-4 text-slate-700 opacity-20" size={48} />
              </div>
              <div className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700/50 shadow-lg relative overflow-hidden">
                <div className="text-slate-500 text-[10px] uppercase font-bold tracking-widest mb-1">Thermal State</div>
                <div className="text-3xl font-mono font-bold text-amber-400">{state.temperatureCelsius?.toFixed(1)}°C</div>
                <div className={`w-full bg-slate-900/50 h-1.5 rounded-full mt-3 border border-slate-700/50 overflow-hidden`}>
                  <div 
                    className={`h-full transition-all duration-500 ${(state.temperatureCelsius ?? 0) > 45 ? 'bg-red-500 animate-pulse' : 'bg-amber-400'}`} 
                    style={{ width: `${Math.min(100, ((state.temperatureCelsius ?? 0) / 60) * 100)}%` }} 
                  />
                </div>
              </div>
            </div>

            {/* Visual Charts */}
            <section className="bg-slate-800/50 rounded-2xl p-6 border border-slate-700 shadow-xl">
              <h2 className="text-sm font-bold uppercase tracking-widest mb-6 flex items-center gap-2 text-slate-300">
                <Activity className="text-blue-400" size={16} /> Static Discharge Profile
              </h2>
              <div className="h-[280px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={chartData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                    <defs>
                      <linearGradient id="curveGrad" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.2}/>
                        <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
                    <XAxis dataKey="soc" hide />
                    <YAxis stroke="#475569" tick={{ fontSize: 10 }} domain={['auto', 'auto']} />
                    <Tooltip 
                      contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155', borderRadius: '12px' }}
                      itemStyle={{ color: '#60a5fa', fontSize: '12px' }}
                    />
                    <Area type="monotone" dataKey="voltage" stroke="#3b82f6" strokeWidth={2} fill="url(#curveGrad)" />
                    <ReferenceLine x={state.socPercentage} stroke="#fbbf24" strokeWidth={2} strokeDasharray="5 5" />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            </section>

            {/* Engineer Insights */}
            <section className={`bg-slate-800/50 rounded-2xl p-6 border border-slate-700 shadow-xl transition-all ${aiInsights || isAiLoading ? 'opacity-100' : 'opacity-40'}`}>
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-sm font-bold uppercase tracking-widest flex items-center gap-2 text-slate-300">
                  <Zap className="text-amber-400" size={16} /> Engineer Assessment
                </h2>
                <button 
                  onClick={async () => {
                    setIsAiLoading(true);
                    const res = await getBatteryInsights(config.chemistry, state.measuredVoltage, state.socPercentage, config.seriesCount, state.bmsVoltage, config.totalCapacityAh, config.chargeRateC);
                    setAiInsights(res || 'Analysis failed.');
                    setIsAiLoading(false);
                  }}
                  className="bg-blue-600/20 text-blue-400 hover:bg-blue-600/30 px-3 py-1 rounded-lg text-xs font-bold uppercase tracking-wider transition-all"
                  disabled={isAiLoading}
                >
                  {isAiLoading ? 'Processing...' : 'Run Analysis'}
                </button>
              </div>
              {aiInsights ? (
                <div className="text-xs text-slate-300 leading-relaxed whitespace-pre-line max-h-[250px] overflow-y-auto font-mono bg-slate-900/50 p-4 rounded-xl border border-slate-700">
                  {aiInsights}
                </div>
              ) : (
                <div className="flex flex-col items-center justify-center py-10 text-center opacity-50">
                  <Activity size={32} className="mb-2" />
                  <p className="text-xs">Provide system data to generate a detailed engineer assessment.</p>
                </div>
              )}
            </section>
          </div>
        </div>
      ) : (
        /* History View */
        <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
            <div className="lg:col-span-12">
              <section className="bg-slate-800/50 rounded-2xl p-6 border border-slate-700 shadow-xl">
                <div className="flex items-center justify-between mb-8">
                  <h2 className="text-sm font-bold uppercase tracking-widest flex items-center gap-2 text-slate-300">
                    <TrendingUp className="text-blue-400" size={16} /> Session Trends
                  </h2>
                  <button 
                    onClick={() => setHistory([])}
                    className="text-red-400 hover:bg-red-400/10 px-3 py-1 rounded-lg text-[10px] font-bold uppercase tracking-widest transition-all flex items-center gap-1 border border-red-400/30"
                  >
                    <Trash2 size={12} /> Clear Log
                  </button>
                </div>

                {history.length > 1 ? (
                  <div className="h-[350px] w-full">
                    <ResponsiveContainer width="100%" height="100%">
                      <LineChart data={historyTrendData}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
                        <XAxis dataKey="time" stroke="#475569" tick={{fontSize: 10}} />
                        <YAxis yAxisId="left" stroke="#3b82f6" orientation="left" tick={{fontSize: 10}} domain={['auto', 'auto']} />
                        <YAxis yAxisId="right" stroke="#10b981" orientation="right" tick={{fontSize: 10}} domain={[0, 100]} />
                        <Tooltip 
                          contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155', borderRadius: '12px' }}
                        />
                        <Legend wrapperStyle={{ paddingTop: '20px' }} />
                        <Line yAxisId="left" type="monotone" dataKey="voltage" stroke="#3b82f6" strokeWidth={3} dot={{r: 4, fill: '#3b82f6'}} activeDot={{ r: 6 }} name="Voltage (V)" />
                        <Line yAxisId="right" type="monotone" dataKey="soc" stroke="#10b981" strokeWidth={3} dot={{r: 4, fill: '#10b981'}} name="SOC (%)" />
                        <Line yAxisId="left" type="monotone" dataKey="temp" stroke="#f59e0b" strokeWidth={2} dot={{r: 3}} name="Temp (°C)" />
                      </LineChart>
                    </ResponsiveContainer>
                  </div>
                ) : (
                  <div className="h-[200px] flex items-center justify-center text-slate-500 text-xs italic border-2 border-dashed border-slate-700 rounded-2xl">
                    Collect at least 2 snapshots to visualize trends.
                  </div>
                )}
              </section>
            </div>

            <div className="lg:col-span-12">
              <section className="bg-slate-800/50 rounded-2xl border border-slate-700 shadow-xl overflow-hidden">
                <div className="p-6 border-b border-slate-700 flex justify-between items-center">
                  <h2 className="text-sm font-bold uppercase tracking-widest flex items-center gap-2 text-slate-300">
                    <Clock className="text-emerald-400" size={16} /> Point-in-Time Data Log
                  </h2>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left text-xs">
                    <thead className="bg-slate-900/50 text-slate-500 uppercase tracking-tighter font-bold">
                      <tr>
                        <th className="px-6 py-4">Timestamp</th>
                        <th className="px-6 py-4">Pack Voltage</th>
                        <th className="px-6 py-4">SOC (%)</th>
                        <th className="px-6 py-4">Cell Avg</th>
                        <th className="px-6 py-4">Temp</th>
                        <th className="px-6 py-4">Current</th>
                        <th className="px-6 py-4 text-right">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-700">
                      {history.length > 0 ? history.map((point) => (
                        <tr key={point.id} className="hover:bg-slate-700/30 transition-colors group">
                          <td className="px-6 py-4 font-mono text-slate-300">{new Date(point.timestamp).toLocaleString()}</td>
                          <td className="px-6 py-4 font-bold text-blue-400">{point.measuredVoltage.toFixed(2)}V</td>
                          <td className="px-6 py-4 font-bold text-emerald-400">{point.socPercentage.toFixed(1)}%</td>
                          <td className="px-6 py-4 text-slate-400">{(point.measuredVoltage / config.seriesCount).toFixed(3)}V</td>
                          <td className="px-6 py-4 text-amber-400">{point.temperatureCelsius?.toFixed(1)}°C</td>
                          <td className="px-6 py-4 text-slate-300">{point.currentAmps}A</td>
                          <td className="px-6 py-4 text-right">
                            <button 
                              onClick={() => {
                                setState(point);
                                setActiveTab('dashboard');
                              }}
                              className="text-blue-400 hover:text-blue-300 font-bold uppercase text-[10px] tracking-widest opacity-0 group-hover:opacity-100 transition-opacity"
                            >
                              Restore
                            </button>
                          </td>
                        </tr>
                      )) : (
                        <tr>
                          <td colSpan={7} className="px-6 py-10 text-center text-slate-500 italic">No history records found. Sync a BMS CSV or capture a snapshot to begin logging.</td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </section>
            </div>
          </div>
        </div>
      )}

      <footer className="text-center text-slate-600 text-[10px] uppercase tracking-widest pt-8 pb-4">
        Lithium Calculator By Han &bull; LFP 15S Specialty Config &bull; Professional Battery Analytics &bull; 2024
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useCallback, useRef } from 'react';
import { 
  Zap, 
  Battery, 
  Activity, 
  Settings, 
  RefreshCw,
  RotateCcw,
  LayoutDashboard,
  FileUp,
  CheckCircle2,
  AlertCircle,
  History as HistoryIcon,
  Trash2,
  Thermometer,
  Clock,
  TrendingUp,
  Download
} from 'lucide-react';
import { 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  AreaChart,
  Area,
  ReferenceLine,
  LineChart,
  Line,
  Legend
} from 'recharts';
import { BatteryChemistry, BatteryConfig, BatteryState, CapacityUnit, EnergyUnit, HistoryPoint } from './types';
import { CHEMISTRY_DEFAULTS, SOC_MAPS } from './constants';
import { getSOCFromVoltage, getVoltageFromSOC } from './utils';
import { getBatteryInsights } from './geminiService';

const INITIAL_CONFIG: BatteryConfig = {
  chemistry: BatteryChemistry.LIFEPO4,
  seriesCount: 15, 
  totalCapacityAh: 200,
  nominalCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].nominal,
  maxCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].max,
  minCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].min,
  chargeRateC: 0.5
};

const INITIAL_STATE: BatteryState = {
  measuredVoltage: 49.5,
  bmsVoltage: 49.5,
  remainingCapacityAh: 160,
  socPercentage: 80,
  currentAmps: 0,
  temperatureCelsius: 25
};

const App: React.FC = () => {
  const [config, setConfig] = useState<BatteryConfig>(INITIAL_CONFIG);
  const [state, setState] = useState<BatteryState>(INITIAL_STATE);
  const [history, setHistory] = useState<HistoryPoint[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'history'>('dashboard');
  const [capacityUnit, setCapacityUnit] = useState<CapacityUnit>('Ah');
  const [energyUnit, setEnergyUnit] = useState<EnergyUnit>('kWh');
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState<boolean>(false);
  const [uploadStatus, setUploadStatus] = useState<{ type: 'success' | 'error' | 'idle', message: string }>({ type: 'idle', message: '' });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const capacityToDisplay = (ah: number) => capacityUnit === 'mAh' ? ah * 1000 : ah;
  const displayToCapacity = (val: number) => capacityUnit === 'mAh' ? val / 1000 : val;
  const energyToDisplay = (wh: number) => energyUnit === 'kWh' ? wh / 1000 : wh;

  const totalEnergyWh = useMemo(() => 
    config.totalCapacityAh * config.nominalCellVoltage * config.seriesCount, 
  [config.totalCapacityAh, config.nominalCellVoltage, config.seriesCount]);

  const currentCellVoltage = state.measuredVoltage / config.seriesCount;

  const logCurrentState = useCallback((overrides?: Partial<BatteryState>) => {
    const entry: HistoryPoint = {
      ...state,
      ...overrides,
      timestamp: Date.now(),
      id: crypto.randomUUID()
    };
    setHistory(prev => [entry, ...prev].slice(0, 100)); // Keep last 100 entries
  }, [state]);

  const handleReset = useCallback(() => {
    setConfig(INITIAL_CONFIG);
    setState(INITIAL_STATE);
    setHistory([]);
    setAiInsights('');
    setUploadStatus({ type: 'idle', message: '' });
    setActiveTab('dashboard');
  }, []);

  const updateFromVoltage = useCallback((voltage: number) => {
    const cellV = voltage / config.seriesCount;
    const soc = getSOCFromVoltage(cellV, config.chemistry);
    setState(prev => ({
      ...prev,
      measuredVoltage: voltage,
      socPercentage: soc,
      remainingCapacityAh: (soc / 100) * config.totalCapacityAh
    }));
  }, [config.seriesCount, config.chemistry, config.totalCapacityAh]);

  const calculateVoltageFromSOC = useCallback((soc: number) => {
    const safeSoc = Math.min(100, Math.max(0, soc));
    const cellV = getVoltageFromSOC(safeSoc, config.chemistry);
    setState(prev => ({ 
      ...prev, 
      socPercentage: safeSoc,
      measuredVoltage: parseFloat((cellV * config.seriesCount).toFixed(2)),
      remainingCapacityAh: (safeSoc / 100) * config.totalCapacityAh
    }));
  }, [config.chemistry, config.seriesCount, config.totalCapacityAh]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (!text) return;

      try {
        const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
        if (lines.length < 2) throw new Error("File contains no data rows.");

        const firstLine = lines[0];
        const delimiters = [',', ';', '\t'];
        const delimiterCounts = delimiters.map(d => (firstLine.match(new RegExp(d, 'g')) || []).length);
        const maxDelimiterIdx = delimiterCounts.indexOf(Math.max(...delimiterCounts));
        const delimiter = delimiterCounts[maxDelimiterIdx] > 0 ? delimiters[maxDelimiterIdx] : ',';

        const headers = lines[0].toLowerCase().split(delimiter).map(h => h.trim());
        let dataRow: string[] = [];
        for (let i = lines.length - 1; i >= 1; i--) {
          const row = lines[i].split(delimiter).map(d => d.trim());
          if (row.length >= headers.length && row.some(cell => !isNaN(parseFloat(cell)))) {
            dataRow = row;
            break;
          }
        }

        if (dataRow.length === 0) throw new Error("No valid data rows found in the CSV.");

        const getVal = (keywords: string[]) => {
          const index = headers.findIndex(h => keywords.some(k => h.includes(k)));
          if (index === -1) return null;
          const val = parseFloat(dataRow[index]);
          return isNaN(val) ? null : val;
        };

        const importedVoltage = getVal(['volt', 'v_pack', 'pack_v', 'total_v', 'battery_v', 'voltage']);
        const importedSoc = getVal(['soc', 'percent', 'cap_%', 'capacity_%', 'charge_%', 'state_of_charge']);
        const importedCurrent = getVal(['curr', 'amp', 'i_pack', 'current', 'pack_i', 'discharge_a', 'charge_a']);
        const importedCapacity = getVal(['rem', 'capacity_ah', 'ah_rem', 'left_ah', 'remaining_cap', 'capacity_remaining']);
        const importedBmsV = getVal(['bms_v', 'internal_v', 'cell_sum', 'bms_voltage']);
        const importedTemp = getVal(['temp', 'cel', 't_pack', 't_ambient', 'temperature']);

        if (importedVoltage === null && importedSoc === null) {
          throw new Error("Missing essential columns: Could not find Pack Voltage or SOC.");
        }

        const nextState: BatteryState = {
          ...state,
          measuredVoltage: importedVoltage ?? state.measuredVoltage,
          bmsVoltage: importedBmsV ?? importedVoltage ?? state.bmsVoltage,
          currentAmps: importedCurrent ?? state.currentAmps,
          temperatureCelsius: importedTemp ?? state.temperatureCelsius
        };

        if (importedSoc !== null) {
          nextState.socPercentage = Math.min(100, Math.max(0, importedSoc));
          nextState.remainingCapacityAh = (nextState.socPercentage / 100) * config.totalCapacityAh;
        } else if (importedVoltage !== null) {
          const soc = getSOCFromVoltage(importedVoltage / config.seriesCount, config.chemistry);
          nextState.socPercentage = soc;
          nextState.remainingCapacityAh = (soc / 100) * config.totalCapacityAh;
        }

        if (importedCapacity !== null) {
          nextState.remainingCapacityAh = importedCapacity;
          nextState.socPercentage = Math.min(100, (importedCapacity / config.totalCapacityAh) * 100);
        }

        setState(nextState);
        logCurrentState(nextState); // Auto-log on sync
        setUploadStatus({ 
          type: 'success', 
          message: `Successfully synchronized and logged data from ${file.name}.` 
        });
      } catch (err) {
        setUploadStatus({ 
          type: 'error', 
          message: `${err instanceof Error ? err.message : 'Invalid CSV format.'}` 
        });
      }
    };
    reader.readAsText(file);
    event.target.value = '';
  };

  const chartData = useMemo(() => {
    return SOC_MAPS[config.chemistry].map(point => ({
      soc: point.soc,
      voltage: parseFloat((point.v * config.seriesCount).toFixed(2)),
      cellVoltage: parseFloat(point.v.toFixed(3))
    })).sort((a, b) => a.soc - b.soc);
  }, [config.chemistry, config.seriesCount]);

  const historyTrendData = useMemo(() => {
    return [...history].reverse().map(h => ({
      time: new Date(h.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
      voltage: h.measuredVoltage,
      soc: h.socPercentage,
      temp: h.temperatureCelsius
    }));
  }, [history]);

  const UnitToggle = ({ value, options, onChange }: { value: string, options: string[], onChange: (v: any) => void }) => (
    <div className="flex bg-slate-900 rounded-lg p-0.5 border border-slate-700 h-6">
      {options.map(opt => (
        <button
          key={opt}
          onClick={() => onChange(opt)}
          className={`px-2 text-[8px] font-bold uppercase tracking-widest rounded transition-all ${value === opt ? 'bg-blue-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}
        >
          {opt}
        </button>
      ))}
    </div>
  );

  return (
    <div className="min-h-screen p-4 md:p-8 max-w-7xl mx-auto space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-slate-700 pb-6">
        <div>
          <h1 className="text-3xl font-bold flex items-center gap-2 text-blue-400">
            <Zap className="fill-blue-400" /> Lithium Calculator By Han
          </h1>
          <div className="flex items-center gap-4 mt-2">
            <button 
              onClick={() => setActiveTab('dashboard')}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-widest transition-all ${activeTab === 'dashboard' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-800 text-slate-400 hover:text-slate-200'}`}
            >
              <LayoutDashboard size={14} /> Dashboard
            </button>
            <button 
              onClick={() => setActiveTab('history')}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-widest transition-all ${activeTab === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-800 text-slate-400 hover:text-slate-200'}`}
            >
              <HistoryIcon size={14} /> History Log {history.length > 0 && <span className="ml-1 opacity-60">({history.length})</span>}
            </button>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <input 
            type="file" 
            accept=".csv" 
            className="hidden" 
            ref={fileInputRef} 
            onChange={handleFileUpload} 
          />
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 transition-all px-4 py-2.5 rounded-xl font-semibold text-sm active:scale-95 group"
          >
            <FileUp className="w-4 h-4 text-emerald-400 group-hover:scale-110 transition-transform" />
            Sync BMS CSV
          </button>
          <button 
            onClick={handleReset}
            className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 transition-all px-4 py-2.5 rounded-xl font-semibold text-sm active:scale-95 text-red-400"
          >
            <RotateCcw className="w-4 h-4" />
            Reset
          </button>
        </div>
      </header>

      {uploadStatus.type !== 'idle' && (
        <div className={`flex items-center gap-3 px-4 py-3 rounded-xl border ${uploadStatus.type === 'success' ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' : 'bg-red-500/10 border-red-500/30 text-red-400'} animate-in slide-in-from-top-4 duration-300`}>
          {uploadStatus.type === 'success' ? <CheckCircle2 size={18} /> : <AlertCircle size={18} />}
          <span className="text-sm font-medium">{uploadStatus.message}</span>
          <button onClick={() => setUploadStatus({ type: 'idle', message: '' })} className="ml-auto opacity-50 hover:opacity-100">✕</button>
        </div>
      )}

      {activeTab === 'dashboard' ? (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 animate-in fade-in duration-500">
          <div className="lg:col-span-4 space-y-6">
            {/* Configuration Section */}
            <section className="bg-slate-800/50 backdrop-blur-sm rounded-2xl p-6 border border-slate-700 shadow-xl">
              <div className="flex items-center gap-2 text-blue-400 font-bold uppercase text-xs tracking-wider mb-6">
                <Settings size={16} /> Configuration
              </div>
              <div className="space-y-4">
                <div>
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Battery Chemistry</label>
                  <select 
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 transition-all text-sm cursor-pointer"
                    value={config.chemistry}
                    onChange={(e) => setConfig(prev => ({ ...prev, chemistry: e.target.value as BatteryChemistry }))}
                  >
                    {Object.values(BatteryChemistry).map(c => (
                      <option key={c} value={c}>{c}</option>
                    ))}
                  </select>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Cell Count (S)</label>
                    <input 
                      type="number" 
                      className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500"
                      value={config.seriesCount}
                      onChange={(e) => setConfig(prev => ({ ...prev, seriesCount: Math.max(1, parseInt(e.target.value) || 1) }))}
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Charge Rate (C)</label>
                    <input 
                      type="number" step="0.01" 
                      className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono text-blue-400"
                      value={config.chargeRateC}
                      onChange={(e) => setConfig(prev => ({ ...prev, chargeRateC: parseFloat(e.target.value) || 0.01 }))}
                    />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <div className="flex justify-between items-center mb-1.5 ml-1">
                      <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold">Total Capacity</label>
                      <UnitToggle value={capacityUnit} options={['Ah', 'mAh']} onChange={setCapacityUnit} />
                    </div>
                    <input 
