import React, { useState, useMemo, useCallback, useRef } from 'react';
import { 
  Zap, 
  Battery, 
  Activity, 
  Settings, 
  RefreshCw,
  RotateCcw,
  LayoutDashboard,
  FileUp,
  CheckCircle2,
  AlertCircle,
  History as HistoryIcon,
  Trash2,
  Thermometer,
  Clock,
  TrendingUp,
  LineChart as LineChartIcon
} from 'lucide-react';
import { 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  AreaChart,
  Area,
  ReferenceLine,
  LineChart,
  Line,
  Legend,
  ScatterChart,
  Scatter,
  ZAxis
} from 'recharts';
import { BatteryChemistry, BatteryConfig, BatteryState, CapacityUnit, EnergyUnit, HistoryPoint } from './types';
import { CHEMISTRY_DEFAULTS, SOC_MAPS } from './constants';
import { getSOCFromVoltage, getVoltageFromSOC } from './utils';
import { getBatteryInsights } from './geminiService';

const INITIAL_CONFIG: BatteryConfig = {
  chemistry: BatteryChemistry.LIFEPO4,
  seriesCount: 15, 
  totalCapacityAh: 200,
  nominalCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].nominal,
  maxCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].max,
  minCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].min,
  chargeRateC: 0.5
};

const INITIAL_STATE: BatteryState = {
  measuredVoltage: 49.5,
  bmsVoltage: 49.5,
  remainingCapacityAh: 160,
  socPercentage: 80,
  currentAmps: 0,
  temperatureCelsius: 25
};

const App: React.FC = () => {
  const [config, setConfig] = useState<BatteryConfig>(INITIAL_CONFIG);
  const [state, setState] = useState<BatteryState>(INITIAL_STATE);
  const [history, setHistory] = useState<HistoryPoint[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'history'>('dashboard');
  const [capacityUnit, setCapacityUnit] = useState<CapacityUnit>('Ah');
  const [energyUnit, setEnergyUnit] = useState<EnergyUnit>('kWh');
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState<boolean>(false);
  const [uploadStatus, setUploadStatus] = useState<{ type: 'success' | 'error' | 'idle', message: string }>({ type: 'idle', message: '' });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const capacityToDisplay = (ah: number) => capacityUnit === 'mAh' ? ah * 1000 : ah;
  const displayToCapacity = (val: number) => capacityUnit === 'mAh' ? val / 1000 : val;
  const energyToDisplay = (wh: number) => energyUnit === 'kWh' ? wh / 1000 : wh;

  const totalEnergyWh = useMemo(() => 
    config.totalCapacityAh * config.nominalCellVoltage * config.seriesCount, 
  [config.totalCapacityAh, config.nominalCellVoltage, config.seriesCount]);

  const currentCellVoltage = state.measuredVoltage / config.seriesCount;

  const logCurrentState = useCallback((overrides?: Partial<BatteryState>) => {
    const entry: HistoryPoint = {
      ...state,
      ...overrides,
      timestamp: Date.now(),
      id: crypto.randomUUID()
    };
    setHistory(prev => [entry, ...prev].slice(0, 100)); // Keep last 100 entries
  }, [state]);

  const handleReset = useCallback(() => {
    setConfig(INITIAL_CONFIG);
    setState(INITIAL_STATE);
    setHistory([]);
    setAiInsights('');
    setUploadStatus({ type: 'idle', message: '' });
    setActiveTab('dashboard');
  }, []);

  const updateFromVoltage = useCallback((voltage: number) => {
    const cellV = voltage / config.seriesCount;
    const soc = getSOCFromVoltage(cellV, config.chemistry);
    setState(prev => ({
      ...prev,
      measuredVoltage: voltage,
      socPercentage: soc,
      remainingCapacityAh: (soc / 100) * config.totalCapacityAh
    }));
  }, [config.seriesCount, config.chemistry, config.totalCapacityAh]);

  const calculateVoltageFromSOC = useCallback((soc: number) => {
    const safeSoc = Math.min(100, Math.max(0, soc));
    const cellV = getVoltageFromSOC(safeSoc, config.chemistry);
    setState(prev => ({ 
      ...prev, 
      socPercentage: safeSoc,
      measuredVoltage: parseFloat((cellV * config.seriesCount).toFixed(2)),
      remainingCapacityAh: (safeSoc / 100) * config.totalCapacityAh
    }));
  }, [config.chemistry, config.seriesCount, config.totalCapacityAh]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (!text) return;

      try {
        const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
        if (lines.length < 2) throw new Error("File contains no data rows.");

        const firstLine = lines[0];
        const delimiters = [',', ';', '\t'];
        const delimiterCounts = delimiters.map(d => (firstLine.match(new RegExp(d, 'g')) || []).length);
        const maxDelimiterIdx = delimiterCounts.indexOf(Math.max(...delimiterCounts));
        const delimiter = delimiterCounts[maxDelimiterIdx] > 0 ? delimiters[maxDelimiterIdx] : ',';

        const headers = lines[0].toLowerCase().split(delimiter).map(h => h.trim());
        let dataRow: string[] = [];
        for (let i = lines.length - 1; i >= 1; i--) {
          const row = lines[i].split(delimiter).map(d => d.trim());
          if (row.length >= headers.length && row.some(cell => !isNaN(parseFloat(cell)))) {
            dataRow = row;
            break;
          }
        }

        if (dataRow.length === 0) throw new Error("No valid data rows found in the CSV.");

        const getVal = (keywords: string[]) => {
          const index = headers.findIndex(h => keywords.some(k => h.includes(k)));
          if (index === -1) return null;
          const val = parseFloat(dataRow[index]);
          return isNaN(val) ? null : val;
        };

        const importedVoltage = getVal(['volt', 'v_pack', 'pack_v', 'total_v', 'battery_v', 'voltage']);
        const importedSoc = getVal(['soc', 'percent', 'cap_%', 'capacity_%', 'charge_%', 'state_of_charge']);
        const importedCurrent = getVal(['curr', 'amp', 'i_pack', 'current', 'pack_i', 'discharge_a', 'charge_a']);
        const importedCapacity = getVal(['rem', 'capacity_ah', 'ah_rem', 'left_ah', 'remaining_cap', 'capacity_remaining']);
        const importedBmsV = getVal(['bms_v', 'internal_v', 'cell_sum', 'bms_voltage']);
        const importedTemp = getVal(['temp', 'cel', 't_pack', 't_ambient', 'temperature']);

        if (importedVoltage === null && importedSoc === null) {
          throw new Error("Missing essential columns: Could not find Pack Voltage or SOC.");
        }

        const nextState: BatteryState = {
          ...state,
          measuredVoltage: importedVoltage ?? state.measuredVoltage,
          bmsVoltage: importedBmsV ?? importedVoltage ?? state.bmsVoltage,
          currentAmps: importedCurrent ?? state.currentAmps,
          temperatureCelsius: importedTemp ?? state.temperatureCelsius
        };

        if (importedSoc !== null) {
          nextState.socPercentage = Math.min(100, Math.max(0, importedSoc));
          nextState.remainingCapacityAh = (nextState.socPercentage / 100) * config.totalCapacityAh;
        } else if (importedVoltage !== null) {
          const soc = getSOCFromVoltage(importedVoltage / config.seriesCount, config.chemistry);
          nextState.socPercentage = soc;
          nextState.remainingCapacityAh = (soc / 100) * config.totalCapacityAh;
        }

        if (importedCapacity !== null) {
          nextState.remainingCapacityAh = importedCapacity;
          nextState.socPercentage = Math.min(100, (importedCapacity / config.totalCapacityAh) * 100);
        }

        setState(nextState);
        logCurrentState(nextState); // Auto-log on sync
        setUploadStatus({ 
          type: 'success', 
          message: `Successfully synchronized and logged data from ${file.name}.` 
        });
      } catch (err) {
        setUploadStatus({ 
          type: 'error', 
          message: `${err instanceof Error ? err.message : 'Invalid CSV format.'}` 
        });
      }
    };
    reader.readAsText(file);
    event.target.value = '';
  };

  const chartData = useMemo(() => {
    return SOC_MAPS[config.chemistry].map(point => ({
      soc: point.soc,
      voltage: parseFloat((point.v * config.seriesCount).toFixed(2)),
      cellVoltage: parseFloat(point.v.toFixed(3))
    })).sort((a, b) => a.soc - b.soc);
