                  className="bg-blue-600/20 text-blue-400 hover:bg-blue-600/30 px-3 py-1 rounded-lg text-xs font-bold uppercase tracking-wider transition-all"
                  disabled={isAiLoading}
                >
                  {isAiLoading ? 'Processing...' : 'Run Analysis'}
                </button>
              </div>
              {aiInsights ? (
                <div className="text-xs text-slate-300 leading-relaxed whitespace-pre-line max-h-[250px] overflow-y-auto font-mono bg-slate-900/50 p-4 rounded-xl border border-slate-700">
                  {aiInsights}
                </div>
              ) : (
                <div className="flex flex-col items-center justify-center py-10 text-center opacity-50">
                  <Activity size={32} className="mb-2" />
                  <p className="text-xs">Provide system data to generate a detailed engineer assessment.</p>
                </div>
              )}
            </section>
          </div>
        </div>
      ) : (
        /* History View */
        <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
            <div className="lg:col-span-12">
              <section className="bg-slate-800/50 rounded-2xl p-6 border border-slate-700 shadow-xl">
                <div className="flex items-center justify-between mb-8">
                  <h2 className="text-sm font-bold uppercase tracking-widest flex items-center gap-2 text-slate-300">
                    <TrendingUp className="text-blue-400" size={16} /> Session Trends
                  </h2>
                  <button 
                    onClick={() => setHistory([])}
                    className="text-red-400 hover:bg-red-400/10 px-3 py-1 rounded-lg text-[10px] font-bold uppercase tracking-widest transition-all flex items-center gap-1 border border-red-400/30"
                  >
                    <Trash2 size={12} /> Clear Log
                  </button>
                </div>

                {history.length > 1 ? (
                  <div className="h-[350px] w-full">
                    <ResponsiveContainer width="100%" height="100%">
                      <LineChart data={historyTrendData}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
                        <XAxis dataKey="time" stroke="#475569" tick={{fontSize: 10}} />
                        <YAxis yAxisId="left" stroke="#3b82f6" orientation="left" tick={{fontSize: 10}} domain={['auto', 'auto']} />
                        <YAxis yAxisId="right" stroke="#10b981" orientation="right" tick={{fontSize: 10}} domain={[0, 100]} />
                        <Tooltip 
                          contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155', borderRadius: '12px' }}
                        />
                        <Legend wrapperStyle={{ paddingTop: '20px' }} />
                        <Line yAxisId="left" type="monotone" dataKey="voltage" stroke="#3b82f6" strokeWidth={3} dot={{r: 4, fill: '#3b82f6'}} activeDot={{ r: 6 }} name="Voltage (V)" />
                        <Line yAxisId="right" type="monotone" dataKey="soc" stroke="#10b981" strokeWidth={3} dot={{r: 4, fill: '#10b981'}} name="SOC (%)" />
                        <Line yAxisId="left" type="monotone" dataKey="temp" stroke="#f59e0b" strokeWidth={2} dot={{r: 3}} name="Temp (°C)" />
                        <ReferenceLine yAxisId="right" y={config.cutoffSoc} stroke="#f43f5e" strokeDasharray="3 3" label={{ position: 'right', value: 'Cutoff', fill: '#f43f5e', fontSize: 10 }} />
                      </LineChart>
                    </ResponsiveContainer>
                  </div>
                ) : (
                  <div className="h-[200px] flex items-center justify-center text-slate-500 text-xs italic border-2 border-dashed border-slate-700 rounded-2xl">
                    Collect at least 2 snapshots to visualize trends.
                  </div>
                )}
              </section>
            </div>

            <div className="lg:col-span-12">
              <section className="bg-slate-800/50 rounded-2xl border border-slate-700 shadow-xl overflow-hidden">
                <div className="p-6 border-b border-slate-700 flex justify-between items-center">
                  <h2 className="text-sm font-bold uppercase tracking-widest flex items-center gap-2 text-slate-300">
                    <Clock className="text-emerald-400" size={16} /> Point-in-Time Data Log
                  </h2>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left text-xs">
                    <thead className="bg-slate-900/50 text-slate-500 uppercase tracking-tighter font-bold">
                      <tr>
                        <th className="px-6 py-4">Timestamp</th>
                        <th className="px-6 py-4">Pack Voltage</th>
                        <th className="px-6 py-4">SOC (%)</th>
                        <th className="px-6 py-4">Cell Avg</th>
                        <th className="px-6 py-4">Temp</th>
                        <th className="px-6 py-4">Current</th>
                        <th className="px-6 py-4 text-right">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-700">
                      {history.length > 0 ? history.map((point) => (
                        <tr key={point.id} className={`hover:bg-slate-700/30 transition-colors group ${point.socPercentage < config.cutoffSoc ? 'bg-red-500/5' : ''}`}>
                          <td className="px-6 py-4 font-mono text-slate-300">{new Date(point.timestamp).toLocaleString()}</td>
                          <td className="px-6 py-4 font-bold text-blue-400">{point.measuredVoltage.toFixed(2)}V</td>
                          <td className={`px-6 py-4 font-bold ${point.socPercentage < config.cutoffSoc ? 'text-red-400' : 'text-emerald-400'}`}>
                            {point.socPercentage.toFixed(1)}% {point.socPercentage < config.cutoffSoc && '!'}
                          </td>
                          <td className="px-6 py-4 text-slate-400">{(point.measuredVoltage / config.seriesCount).toFixed(3)}V</td>
                          <td className="px-6 py-4 text-amber-400">{point.temperatureCelsius?.toFixed(1)}°C</td>
                          <td className="px-6 py-4 text-slate-300">{point.currentAmps}A</td>
                          <td className="px-6 py-4 text-right">
                            <button 
                              onClick={() => {
                                setState(point);
                                setActiveTab('dashboard');
                              }}
                              className="text-blue-400 hover:text-blue-300 font-bold uppercase text-[10px] tracking-widest opacity-0 group-hover:opacity-100 transition-opacity"
                            >
                              Restore
                            </button>
                          </td>
                        </tr>
                      )) : (
                        <tr>
                          <td colSpan={7} className="px-6 py-10 text-center text-slate-500 italic">No history records found. Sync a BMS CSV or capture a snapshot to begin logging.</td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </section>
            </div>
          </div>
        </div>
      )}

      <footer className="text-center text-slate-600 text-[10px] uppercase tracking-widest pt-8 pb-4">
        Lithium Calculator By Han &bull; LFP 15S Specialty Config &bull; Professional Battery Analytics &bull; 2024
      </footer>
    </div>
  );
};

export default App;

{
  "name": "Lithium Calculator By Han Win",
  "description": "A professional-grade Lithium-Ion battery calculator that synchronizes voltage, capacity, and energy data with intelligent state-of-charge estimation and visual discharge curves.",
  "requestFramePermissions": []
}

import React, { useState, useMemo, useCallback, useRef, useEffect } from 'react';
import { 
  Zap, 
  Battery, 
  Activity, 
  Settings, 
  RefreshCw,
  RotateCcw,
  LayoutDashboard,
  FileUp,
  CheckCircle2,
  AlertCircle,
  History as HistoryIcon,
  Trash2,
  Thermometer,
  Clock,
  TrendingUp,
  LineChart as LineChartIcon,
  ZapOff,
  Timer,
  ShieldAlert
} from 'lucide-react';
import { 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  AreaChart,
  Area,
  ReferenceLine,
  LineChart,
  Line,
  Legend
} from 'recharts';
import { BatteryChemistry, BatteryConfig, BatteryState, CapacityUnit, EnergyUnit, HistoryPoint } from './types';
import { CHEMISTRY_DEFAULTS, SOC_MAPS } from './constants';
import { getSOCFromVoltage, getVoltageFromSOC } from './utils';
import { getBatteryInsights } from './geminiService';

const INITIAL_CONFIG: BatteryConfig = {
  chemistry: BatteryChemistry.LIFEPO4,
  seriesCount: 15, 
  totalCapacityAh: 200,
  nominalCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].nominal,
  maxCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].max,
  minCellVoltage: CHEMISTRY_DEFAULTS[BatteryChemistry.LIFEPO4].min,
  chargeRateC: 0.5,
  cutoffSoc: 20 // Default cutoff at 20%
};

const INITIAL_STATE: BatteryState = {
  measuredVoltage: 49.5,
  bmsVoltage: 49.5,
  remainingCapacityAh: 160,
  socPercentage: 80,
  currentAmps: 0,
  temperatureCelsius: 25,
  dischargeLoadAmps: 0
};

const App: React.FC = () => {
  const [config, setConfig] = useState<BatteryConfig>(INITIAL_CONFIG);
  const [state, setState] = useState<BatteryState>(INITIAL_STATE);
  const [history, setHistory] = useState<HistoryPoint[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'history'>('dashboard');
  const [capacityUnit, setCapacityUnit] = useState<CapacityUnit>('Ah');
  const [energyUnit, setEnergyUnit] = useState<EnergyUnit>('kWh');
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState<boolean>(false);
  const [uploadStatus, setUploadStatus] = useState<{ type: 'success' | 'error' | 'idle', message: string }>({ type: 'idle', message: '' });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const capacityToDisplay = (ah: number) => capacityUnit === 'mAh' ? ah * 1000 : ah;
  const displayToCapacity = (val: number) => capacityUnit === 'mAh' ? val / 1000 : val;
  const energyToDisplay = (wh: number) => energyUnit === 'kWh' ? wh / 1000 : wh;

  const totalEnergyWh = useMemo(() => 
    config.totalCapacityAh * config.nominalCellVoltage * config.seriesCount, 
  [config.totalCapacityAh, config.nominalCellVoltage, config.seriesCount]);

  const currentCellVoltage = state.measuredVoltage / config.seriesCount;

  // Calculate usable capacity based on cutoff
  const usableAh = useMemo(() => {
    const cutoffAh = (config.cutoffSoc / 100) * config.totalCapacityAh;
    return Math.max(0, state.remainingCapacityAh - cutoffAh);
  }, [state.remainingCapacityAh, config.cutoffSoc, config.totalCapacityAh]);

  const usableEnergyWh = useMemo(() => {
    const usableSocRange = Math.max(0, state.socPercentage - config.cutoffSoc);
    return (usableSocRange / 100) * totalEnergyWh;
  }, [state.socPercentage, config.cutoffSoc, totalEnergyWh]);

  // Runtime Calculation (Time to Cutoff)
  const timeToCutoff = useMemo(() => {
    const load = state.dischargeLoadAmps || 0;
    if (load <= 0) return null;
    const hours = usableAh / load;
    const h = Math.floor(hours);
    const m = Math.round((hours - h) * 60);
    return { h, m };
  }, [usableAh, state.dischargeLoadAmps]);

  const logCurrentState = useCallback((overrides?: Partial<BatteryState>) => {
    const entry: HistoryPoint = {
      ...state,
      ...overrides,
      timestamp: Date.now(),
      id: crypto.randomUUID()
    };
    setHistory(prev => [entry, ...prev].slice(0, 100));
  }, [state]);

  const handleReset = useCallback(() => {
    setConfig(INITIAL_CONFIG);
    setState(INITIAL_STATE);
    setHistory([]);
    setAiInsights('');
    setUploadStatus({ type: 'idle', message: '' });
    setActiveTab('dashboard');
  }, []);

  const updateFromVoltage = useCallback((voltage: number) => {
    const cellV = voltage / config.seriesCount;
    const soc = getSOCFromVoltage(cellV, config.chemistry);
    setState(prev => ({
      ...prev,
      measuredVoltage: voltage,
      socPercentage: soc,
      remainingCapacityAh: (soc / 100) * config.totalCapacityAh
    }));
  }, [config.seriesCount, config.chemistry, config.totalCapacityAh]);

  const calculateVoltageFromSOC = useCallback((soc: number) => {
    const safeSoc = Math.min(100, Math.max(0, soc));
    const cellV = getVoltageFromSOC(safeSoc, config.chemistry);
    setState(prev => ({ 
      ...prev, 
      socPercentage: safeSoc,
      measuredVoltage: parseFloat((cellV * config.seriesCount).toFixed(2)),
      remainingCapacityAh: (safeSoc / 100) * config.totalCapacityAh
    }));
  }, [config.chemistry, config.seriesCount, config.totalCapacityAh]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (!text) return;
      try {
        const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
        if (lines.length < 2) throw new Error("File contains no data rows.");
        const firstLine = lines[0];
        const delimiters = [',', ';', '\t'];
        const delimiterCounts = delimiters.map(d => (firstLine.match(new RegExp(d, 'g')) || []).length);
        const maxDelimiterIdx = delimiterCounts.indexOf(Math.max(...delimiterCounts));
        const delimiter = delimiterCounts[maxDelimiterIdx] > 0 ? delimiters[maxDelimiterIdx] : ',';
        const headers = lines[0].toLowerCase().split(delimiter).map(h => h.trim());
        let dataRow: string[] = [];
        for (let i = lines.length - 1; i >= 1; i--) {
          const row = lines[i].split(delimiter).map(d => d.trim());
          if (row.length >= headers.length && row.some(cell => !isNaN(parseFloat(cell)))) {
            dataRow = row;
            break;
          }
        }
        if (dataRow.length === 0) throw new Error("No valid data rows found in the CSV.");
        const getVal = (keywords: string[]) => {
          const index = headers.findIndex(h => keywords.some(k => h.includes(k)));
          if (index === -1) return null;
          const val = parseFloat(dataRow[index]);
          return isNaN(val) ? null : val;
        };
        const importedVoltage = getVal(['volt', 'v_pack', 'pack_v', 'total_v', 'battery_v', 'voltage']);
        const importedSoc = getVal(['soc', 'percent', 'cap_%', 'capacity_%', 'charge_%', 'state_of_charge']);
        const importedCurrent = getVal(['curr', 'amp', 'i_pack', 'current', 'pack_i', 'discharge_a', 'charge_a']);
        const importedCapacity = getVal(['rem', 'capacity_ah', 'ah_rem', 'left_ah', 'remaining_cap', 'capacity_remaining']);
        const importedBmsV = getVal(['bms_v', 'internal_v', 'cell_sum', 'bms_voltage']);
        const importedTemp = getVal(['temp', 'cel', 't_pack', 't_ambient', 'temperature']);
        if (importedVoltage === null && importedSoc === null) {
          throw new Error("Missing essential columns: Could not find Pack Voltage or SOC.");
        }
        const nextState: BatteryState = {
          ...state,
          measuredVoltage: importedVoltage ?? state.measuredVoltage,
          bmsVoltage: importedBmsV ?? importedVoltage ?? state.bmsVoltage,
          currentAmps: importedCurrent ?? state.currentAmps,
          temperatureCelsius: importedTemp ?? state.temperatureCelsius,
          dischargeLoadAmps: importedCurrent && importedCurrent < 0 ? Math.abs(importedCurrent) : state.dischargeLoadAmps
        };
        if (importedSoc !== null) {
          nextState.socPercentage = Math.min(100, Math.max(0, importedSoc));
          nextState.remainingCapacityAh = (nextState.socPercentage / 100) * config.totalCapacityAh;
        } else if (importedVoltage !== null) {
          const soc = getSOCFromVoltage(importedVoltage / config.seriesCount, config.chemistry);
          nextState.socPercentage = soc;
          nextState.remainingCapacityAh = (soc / 100) * config.totalCapacityAh;
        }
        if (importedCapacity !== null) {
          nextState.remainingCapacityAh = importedCapacity;
          nextState.socPercentage = Math.min(100, (importedCapacity / config.totalCapacityAh) * 100);
        }
        setState(nextState);
        logCurrentState(nextState); 
        setUploadStatus({ 
          type: 'success', 
          message: `Successfully synchronized and logged data from ${file.name}.` 
        });
      } catch (err) {
        setUploadStatus({ 
          type: 'error', 
          message: `${err instanceof Error ? err.message : 'Invalid CSV format.'}` 
        });
      }
    };
    reader.readAsText(file);
    event.target.value = '';
  };

  const chartData = useMemo(() => {
    return SOC_MAPS[config.chemistry].map(point => ({
      soc: point.soc,
      voltage: parseFloat((point.v * config.seriesCount).toFixed(2)),
      cellVoltage: parseFloat(point.v.toFixed(3))
    })).sort((a, b) => a.soc - b.soc);
  }, [config.chemistry, config.seriesCount]);

  const historyTrendData = useMemo(() => {
    return [...history].reverse().map(h => ({
      time: new Date(h.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
      voltage: h.measuredVoltage,
      soc: h.socPercentage,
      temp: h.temperatureCelsius
    }));
  }, [history]);

  const observedCurveData = useMemo(() => {
    return [...history]
      .sort((a, b) => a.socPercentage - b.socPercentage)
      .map(h => ({
        soc: parseFloat(h.socPercentage.toFixed(1)),
        voltage: parseFloat(h.measuredVoltage.toFixed(2)),
        timestamp: h.timestamp
      }));
  }, [history]);

  const UnitToggle = ({ value, options, onChange }: { value: string, options: string[], onChange: (v: any) => void }) => (
    <div className="flex bg-slate-900 rounded-lg p-0.5 border border-slate-700 h-6">
      {options.map(opt => (
        <button
          key={opt}
          onClick={() => onChange(opt)}
          className={`px-2 text-[8px] font-bold uppercase tracking-widest rounded transition-all ${value === opt ? 'bg-blue-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}
        >
          {opt}
        </button>
      ))}
    </div>
  );

  return (
    <div className="min-h-screen p-4 md:p-8 max-w-7xl mx-auto space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-slate-700 pb-6">
        <div>
          <h1 className="text-3xl font-bold flex items-center gap-2 text-blue-400">
            <Zap className="fill-blue-400" /> Lithium Calculator By Han Win
          </h1>
          <div className="flex items-center gap-4 mt-2">
            <button 
              onClick={() => setActiveTab('dashboard')}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-widest transition-all ${activeTab === 'dashboard' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-800 text-slate-400 hover:text-slate-200'}`}
            >
              <LayoutDashboard size={14} /> Dashboard
            </button>
            <button 
              onClick={() => setActiveTab('history')}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-widest transition-all ${activeTab === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-800 text-slate-400 hover:text-slate-200'}`}
            >
              <HistoryIcon size={14} /> History Log {history.length > 0 && <span className="ml-1 opacity-60">({history.length})</span>}
            </button>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <input 
            type="file" 
            accept=".csv" 
            className="hidden" 
            ref={fileInputRef} 
            onChange={handleFileUpload} 
          />
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 transition-all px-4 py-2.5 rounded-xl font-semibold text-sm active:scale-95 group"
          >
            <FileUp className="w-4 h-4 text-emerald-400 group-hover:scale-110 transition-transform" />
            Sync BMS CSV
          </button>
          <button 
            onClick={handleReset}
            className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 transition-all px-4 py-2.5 rounded-xl font-semibold text-sm active:scale-95 text-red-400"
          >
            <RotateCcw className="w-4 h-4" />
            Reset
          </button>
        </div>
      </header>

      {uploadStatus.type !== 'idle' && (
        <div className={`flex items-center gap-3 px-4 py-3 rounded-xl border ${uploadStatus.type === 'success' ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' : 'bg-red-500/10 border-red-500/30 text-red-400'} animate-in slide-in-from-top-4 duration-300`}>
          {uploadStatus.type === 'success' ? <CheckCircle2 size={18} /> : <AlertCircle size={18} />}
          <span className="text-sm font-medium">{uploadStatus.message}</span>
          <button onClick={() => setUploadStatus({ type: 'idle', message: '' })} className="ml-auto opacity-50 hover:opacity-100">✕</button>
        </div>
      )}

      {activeTab === 'dashboard' ? (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 animate-in fade-in duration-500">
          <div className="lg:col-span-4 space-y-6">
            {/* Configuration Section */}
            <section className="bg-slate-800/50 backdrop-blur-sm rounded-2xl p-6 border border-slate-700 shadow-xl">
              <div className="flex items-center gap-2 text-blue-400 font-bold uppercase text-xs tracking-wider mb-6">
                <Settings size={16} /> Configuration
              </div>
              <div className="space-y-4">
                <div>
                  <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Battery Chemistry</label>
                  <select 
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 transition-all text-sm cursor-pointer"
                    value={config.chemistry}
                    onChange={(e) => setConfig(prev => ({ ...prev, chemistry: e.target.value as BatteryChemistry }))}
                  >
                    {Object.values(BatteryChemistry).map(c => (
                      <option key={c} value={c}>{c}</option>
                    ))}
                  </select>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Cell Count (S)</label>
                    <input 
                      type="number" 
                      className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono"
                      value={config.seriesCount}
                      onChange={(e) => setConfig(prev => ({ ...prev, seriesCount: Math.max(1, parseInt(e.target.value) || 1) }))}
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Cutoff SOC (%)</label>
                    <div className="relative">
                      <input 
                        type="number" min="0" max="99"
                        className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:ring-2 focus:ring-red-500 font-mono text-red-400 pr-8"
                        value={config.cutoffSoc}
                        onChange={(e) => setConfig(prev => ({ ...prev, cutoffSoc: Math.min(99, Math.max(0, parseInt(e.target.value) || 0)) }))}
                      />
                      <ShieldAlert className="absolute right-3 top-2.5 text-slate-600" size={14} />
                    </div>
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <div className="flex justify-between items-center mb-1.5 ml-1">
                      <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold">Total Capacity</label>
                      <UnitToggle value={capacityUnit} options={['Ah', 'mAh']} onChange={setCapacityUnit} />
                    </div>
                    <input 
                      type="number" step="0.1"
                      className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono"
                      value={capacityToDisplay(config.totalCapacityAh).toFixed(capacityUnit === 'mAh' ? 0 : 2)}
                      onChange={(e) => setConfig(prev => ({ ...prev, totalCapacityAh: displayToCapacity(parseFloat(e.target.value) || 0) }))}
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1.5 ml-1">Charge Rate (C)</label>
                    <input 
                      type="number" step="0.01" 
                      className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-sm outline-none focus:border-blue-500 font-mono text-blue-400"
